/* Tech 3D · Nivell 2 · unitat 1 «Modelar amb instruccions» · guia del professor (p1-1 … p1-5)
   Material propi de Numi. Classe de 60 minuts; mateix esquema que TGUIDE['r1-1']. Les diapositives «media» mostren el
   programa (amb colors) i el model 3D que en surt (TMEDIA.model de tech-model.js); «code» mostra el programa en text. */
Object.assign(TGUIDE, (() => {
  const MON = 'cub(40, 40, 10)\nmou(20, 20, 10) cilindre(20, 30)\nmou(20, 20, 50) esfera(20)';
  const OBE3 = 'mou(0, 0, 4) cub(50, 50, 8, centrat)\nmou(0, 0, 8) cilindre(30, 6)\nmou(0, 0, 14) con(20, 60, 8)', OBE = OBE3 + '\nmou(0, 0, 78) esfera(12)';
  return {
  /* ---------- Sessió 1 · Del ratolí al codi ---------- */
  'p1-1': {
    obj: ["L'alumne/a explica per què es modela amb codi (precisió, repetició i canvis ràpids).|El alumno/a explica por qué se modela con código (precisión, repetición y cambios rápidos).", "L'alumne/a escriu cubs, cilindres, esferes i cons amb les mides en mil·límetres.|El alumno/a escribe cubos, cilindros, esferas y conos con las medidas en milímetros.",
      "L'alumne/a fa servir mou(x, y, z) per col·locar una forma respecte de l'origen.|El alumno/a usa mueve(x, y, z) para colocar una forma respecto del origen.", "L'alumne/a prediu el model que fa un programa curt abans d'executar-lo.|El alumno/a predice el modelo que hace un programa corto antes de ejecutarlo."],
    comp: ['Tecnologia i digitalització: disseny assistit per ordinador (CAD 3D) amb codi|Tecnología y digitalización: diseño asistido por ordenador (CAD 3D) con código', 'Pensament computacional: algorismes com a seqüències d\'instruccions precises|Pensamiento computacional: algoritmos como secuencias de instrucciones precisas', 'Matemàtiques: coordenades en l\'espai i mesura en mil·límetres|Matemáticas: coordenadas en el espacio y medida en milímetros', 'Comunicació: descriure un objecte amb instruccions no ambigües|Comunicación: describir un objeto con instrucciones no ambiguas'],
    vocab: [['Programa|Programa', "Llista d'instruccions en ordre que segueix l'ordinador.|Lista de instrucciones en orden que sigue el ordenador."], ['Instrucció|Instrucción', 'Una ordre del programa, com cub(20) o mou(10, 0, 0).|Una orden del programa, como cubo(20) o mueve(10, 0, 0).'], ['Paràmetre|Parámetro', 'Cada número entre parèntesis: les mides o la posició.|Cada número entre paréntesis: las medidas o la posición.'], ['Origen|Origen', 'El punt (0, 0, 0), des d\'on es mesura tot.|El punto (0, 0, 0), desde donde se mide todo.'], ['OpenSCAD|OpenSCAD', 'Un programa de disseny 3D amb codi que fan servir enginyers i makers.|Un programa de diseño 3D con código que usan ingenieros y makers.']],
    mat: { aula: ["Un ordinador per alumne/a amb Numi Tech obert a la sessió «Del ratolí al codi»|Un ordenador por alumno/a con Numi Tech abierto en la sesión «Del ratón al código»", 'Projector i la presentació de la sessió|Proyector y la presentación de la sesión', 'Peces de construcció (o capses petites) per al dictat 3D, unes 8 per parella|Piezas de construcción (o cajas pequeñas) para el dictado 3D, unas 8 por pareja'],
      imprimir: ['Fitxa: llegeix el programa|Ficha: lee el programa'], prep: ['Preparar les bosses de peces per parelles, iguals per a tothom.|Preparar las bolsas de piezas por parejas, iguales para todos.', 'Provar el repte de l\'esfera a sobre del cub: és el primer que demana pensar en el centre de l\'esfera.|Probar el reto de la esfera encima del cubo: es el primero que pide pensar en el centro de la esfera.', 'Si teniu OpenSCAD instal·lat, obrir-hi un fitxer .scad exportat per ensenyar-lo.|Si tenéis OpenSCAD instalado, abrir un archivo .scad exportado para enseñarlo.'] },
    plan: [
      { min: 5, t: "Benvinguda a l'estudi d'enginyeria|Bienvenida al estudio de ingeniería", fase: 'inici', fa: "Presenta el curs: dissenyaran peces amb codi, com els enginyers. Planteja el problema: 30 suports de mides diferents. Com ho faríeu amb el ratolí?|Presenta el curso: diseñarán piezas con código, como los ingenieros. Plantea el problema: 30 soportes de medidas distintas. ¿Cómo lo haríais con el ratón?",
        diu: ['Si cada client vol una mida diferent, quantes vegades hauríeu de tornar a dibuixar el suport?|Si cada cliente quiere una medida distinta, ¿cuántas veces tendríais que volver a dibujar el soporte?'], slides: ['s1', 's2'], app: 'Encara no: pantalles abaixades.|Todavía no: pantallas bajadas.', org: 'Tot el grup|Todo el grupo' },
      { min: 12, t: 'El programa és la recepta|El programa es la receta', fase: 'teoria', fa: "Presenta les instruccions de forma (cub, cilindre, esfera, con) i mou. Insisteix en dos detalls: el cub té una cantonada a l'origen i l'esfera té el centre a l'origen. Llegiu junts cada programa de les diapositives abans de mirar el model.|Presenta las instrucciones de forma (cubo, cilindro, esfera, cono) y mueve. Insiste en dos detalles: el cubo tiene una esquina en el origen y la esfera tiene el centro en el origen. Leed juntos cada programa de las diapositivas antes de mirar el modelo.",
        diu: ['Quin número és l\'amplada? I l\'alçada?|¿Qué número es la anchura? ¿Y la altura?', "Per què hem hagut de pujar l'esfera 10 mm?|¿Por qué hemos tenido que subir la esfera 10 mm?"], slides: ['s3', 's4', 's5', 's6', 's7'], app: "Encara no: tota l'atenció a la projecció.|Todavía no: toda la atención en la proyección.", org: 'Tot el grup|Todo el grupo' },
      { min: 10, t: 'El dictat 3D|El dictado 3D', fase: 'desconnectat', fa: "Per parelles: un construeix una figura de 4 peces amagada i n'escriu les instruccions; l'altre la reprodueix sense mirar. Després comparen i busquen on les instruccions eren ambigües. Tanca-ho fent notar que el codi no admet ambigüitats: per això fa servir números.|Por parejas: uno construye una figura de 4 piezas escondida y escribe sus instrucciones; el otro la reproduce sin mirar. Después comparan y buscan dónde las instrucciones eran ambiguas. Ciérralo haciendo notar que el código no admite ambigüedades: por eso usa números.",
        diu: ['Quina paraula de les vostres instruccions ha creat confusió?|¿Qué palabra de vuestras instrucciones ha creado confusión?'], slides: ['s8'], app: 'Encara no: peces de construcció.|Todavía no: piezas de construcción.', org: 'Per parelles|Por parejas' },
      { min: 22, t: "A l'ordinador: predir i programar|En el ordenador: predecir y programar", fase: 'ordinador', fa: "Fan la sessió a l'app: prediccions (el programa es llegeix en text) i quatre reptes de programació, del cub a la torre. El primer es fa amb blocs i, mirant la pestanya Codi, veuen que és el mateix programa; els altres s'obren al codi i s'escriuen amb els fragments de sota (tocar «mou(10, 0, 0)» i canviar-ne els números). Passa per les taules al repte de l'esfera: demana que diguin on és el centre del cub abans de tocar els números.|Hacen la sesión en la app: predicciones (el programa se lee en texto) y cuatro retos de programación, del cubo a la torre. El primero se hace con bloques y, mirando la pestaña Código, ven que es el mismo programa; los otros se abren en el código y se escriben con los fragmentos de debajo (tocar «mueve(10, 0, 0)» y cambiar sus números). Pasa por las mesas en el reto de la esfera: pide que digan dónde está el centro del cubo antes de tocar los números.",
        diu: ['On és el centre del cub? I on acaba per dalt?|¿Dónde está el centro del cubo? ¿Y dónde acaba por arriba?', 'Mireu el fantasma des del costat per veure si toca.|Mirad el fantasma desde el lado para ver si toca.'], slides: ['s9', 's10', 's11'], app: "Sessió «Del ratolí al codi», fins al primer disseny lliure.|Sesión «Del ratón al código», hasta el primer diseño libre.", org: 'Individual|Individual' },
      { min: 6, t: 'El primer disseny amb codi|El primer diseño con código', fase: 'crea', fa: "Disseny lliure amb almenys 3 formes i un mou. Proposa idees si cal: un arbre, una làmpada, un robot. Es desa a «Projectes»; qui vulgui pot descarregar el .scad.|Diseño libre con al menos 3 formas y un mueve. Propón ideas si hace falta: un árbol, una lámpara, un robot. Se guarda en «Proyectos»; quien quiera puede descargar el .scad.",
        diu: ['Primer la base, després el que va a sobre.|Primero la base, después lo que va encima.'], slides: ['s12'], app: 'Pas «El teu primer disseny amb codi».|Paso «Tu primer diseño con código».', org: 'Individual|Individual' },
      { min: 5, t: 'Tancament|Cierre', fase: 'tancament', fa: 'Repassa les tres idees clau i el tiquet de sortida.|Repasa las tres ideas clave y el ticket de salida.', diu: ['Què fa mou(0, 0, 20)? On queda la cantonada d\'un cub?|¿Qué hace mueve(0, 0, 20)? ¿Dónde queda la esquina de un cubo?'], slides: ['s13', 's14'], app: "Les últimes preguntes i «Com t'ha anat?».|Las últimas preguntas y «¿Cómo te ha ido?».", org: 'Tot el grup|Todo el grupo' }
    ],
    errors: [["Posa les mides en un ordre diferent (alçada primer).|Pone las medidas en un orden distinto (altura primero).", "Recorda l'ordre de sempre: x, y, z (amplada, fondària, alçada). Que miri la caixa des de dalt i des del costat.|Recuerda el orden de siempre: x, y, z (anchura, fondo, altura). Que mire la caja desde arriba y desde el lado."],
      ["Col·loca l'esfera a z = 20 i queda mig enfonsada al cub.|Coloca la esfera en z = 20 y queda medio hundida en el cubo.", "L'esfera té el centre a l'origen: perquè toqui per sota a z = 20, el centre ha d'anar a z = 20 + 10.|La esfera tiene el centro en el origen: para que toque por debajo en z = 20, el centro tiene que ir en z = 20 + 10."],
      ['Creu que mou mou totes les formes que vénen després.|Cree que mueve mueve todas las formas que vienen después.', 'Només afecta la forma (o el grup { }) que té just després, a la mateixa línia. Que llegeixi el codi línia a línia; si cal, que obri la pestanya Blocs: la forma hi queda dins del bloc mou.|Solo afecta a la forma (o al grupo { }) que tiene justo después, en la misma línea. Que lea el código línea a línea; si hace falta, que abra la pestaña Bloques: la forma queda dentro del bloque mueve.']],
    diff: { mes: "Fer el suport de l'encàrrec: una base i dos cilindres, i després canviar-ne totes les mides perquè sigui el doble de gran. Exportar el .scad i comparar-lo amb el programa.|Hacer el soporte del encargo: una base y dos cilindros, y después cambiar todas sus medidas para que sea el doble de grande. Exportar el .scad y compararlo con el programa.",
      menys: 'Escriure amb els fragments de la pestanya Codi (tocar «cub(20, 20, 20)» i canviar-ne només els números), amb la fitxa al costat, on hi ha l\'ordre dels números de cada forma. Qui ho necessiti pot fer servir la pestanya Blocs. Fer primer els reptes sense mou.|Escribir con los fragmentos de la pestaña Código (tocar «cubo(20, 20, 20)» y cambiar solo los números), con la ficha al lado, donde está el orden de los números de cada forma. Quien lo necesite puede usar la pestaña Bloques. Hacer primero los retos sin mueve.' },
    aval: { ticket: ['Què fa mou(0, 0, 20) davant d\'una forma?|¿Qué hace mueve(0, 0, 20) delante de una forma?', 'Escriu un cub de 40 mm d\'ample, 20 de fons i 10 d\'alt.|Escribe un cubo de 40 mm de ancho, 20 de fondo y 10 de alto.'],
      rubric: [['Formes amb mides|Formas con medidas', 'Escriu cada forma amb els paràmetres en l\'ordre correcte.|Escribe cada forma con los parámetros en el orden correcto.', 'Fa les formes, però confon l\'ordre dels paràmetres.|Hace las formas, pero confunde el orden de los parámetros.'],
        ['Col·locar amb mou|Colocar con mueve', 'Calcula la posició tenint en compte on és l\'origen de cada forma.|Calcula la posición teniendo en cuenta dónde está el origen de cada forma.', 'Col·loca les formes provant números fins que encerta.|Coloca las formas probando números hasta que acierta.'],
        ['Predir|Predecir', 'Prediu el model abans d\'executar i explica per què.|Predice el modelo antes de ejecutar y explica por qué.', 'Encerta algunes prediccions però no les sap justificar.|Acierta algunas predicciones pero no sabe justificarlas.']] },
    casa: "Escriu en un paper les instruccions per fer la teva tassa preferida amb formes (cilindres, cubs…) i les seves mides en mil·límetres. Mesura-la de veritat amb un regle!|Escribe en un papel las instrucciones para hacer tu taza preferida con formas (cilindros, cubos…) y sus medidas en milímetros. ¡Mídela de verdad con una regla!",
    intro: "Primera sessió del nivell 2: l'alumnat passa de pensar «on poso la peça» a pensar «quina instrucció la posa». No cal haver fet el nivell 1.|Primera sesión del nivel 2: el alumnado pasa de pensar «dónde pongo la pieza» a pensar «qué instrucción la pone». No hace falta haber hecho el nivel 1.",
    claus: ["Modelar amb codi fa el disseny precís, repetible i fàcil de canviar.|Modelar con código hace el diseño preciso, repetible y fácil de cambiar.", "cub té una cantonada a l'origen; cilindre i con, el centre de la base; esfera, el centre.|cubo tiene una esquina en el origen; cilindro y cono, el centro de la base; esfera, el centro.", 'mou afecta la forma que ve just després (o el bloc { }).|mueve afecta a la forma que viene justo después (o al bloque { }).', 'Les mides i les posicions són en mil·límetres.|Las medidas y las posiciones son en milímetros.'],
    prev: ['Saber què són les coordenades x, y (i, millor, z).|Saber qué son las coordenadas x, y (y, mejor, z).', 'Saber fer servir el ratolí i el teclat.|Saber usar el ratón y el teclado.', 'No cal haver programat abans.|No hace falta haber programado antes.'],
    faq: [["És el mateix que OpenSCAD?|¿Es lo mismo que OpenSCAD?", "És molt semblant: les mateixes idees amb paraules en català o castellà. El botó «.scad» passa el vostre programa a OpenSCAD de veritat.|Es muy parecido: las mismas ideas con palabras en catalán o castellano. El botón «.scad» pasa vuestro programa a OpenSCAD de verdad."],
      ['Per què el cub no queda centrat a l\'origen?|¿Por qué el cubo no queda centrado en el origen?', "És el conveni d'OpenSCAD: així els números coincideixen amb les cantonades. Si el voleu centrat, poseu-hi «centrat».|Es la convención de OpenSCAD: así los números coinciden con las esquinas. Si lo queréis centrado, ponedle «centrado»."],
      ['Cal escriure codi des del primer dia?|¿Hay que escribir código desde el primer día?', "Sí, però amb ajuda: el primer repte es fa amb blocs i, a partir del segon, els reptes s'obren a la pestanya «Codi», amb una paleta de fragments (tocar «cub(20, 20, 20)» l'escriu i en deixa triat el primer número). La pestanya «Blocs» mostra el mateix programa per a qui la necessiti.|Sí, pero con ayuda: el primer reto se hace con bloques y, a partir del segundo, los retos se abren en la pestaña «Código», con una paleta de fragmentos (tocar «cubo(20, 20, 20)» lo escribe y deja elegido el primer número). La pestaña «Bloques» muestra el mismo programa para quien la necesite."]],
    tec: [["No es veu el model 3D, només el programa.|No se ve el modelo 3D, solo el programa.", "El navegador ha de tenir el 3D (WebGL) activat. Si no, l'app dibuixa una vista més senzilla. Torneu a carregar la pàgina.|El navegador tiene que tener el 3D (WebGL) activado. Si no, la app dibuja una vista más sencilla. Volved a cargar la página."],
      ["Al mòbil costa trobar els parèntesis i les comes.|En el móvil cuesta encontrar los paréntesis y las comas.", "La paleta de fragments de sota el codi té ( ), { }, la coma, + − × ÷, = i «centrat»: toqueu-los i s'escriuen on hi ha el cursor.|La paleta de fragmentos de debajo del código tiene ( ), { }, la coma, + − × ÷, = y «centrado»: tocadlos y se escriben donde está el cursor."],
      ['El fragment s\'escriu en un lloc que no volien.|El fragmento se escribe en un sitio que no querían.', "Els fragments s'escriuen on hi ha el cursor: toqueu primer el lloc del codi (el final d'una línia, per exemple). Una forma o un mou mai no van dins d'uns parèntesis: si el cursor hi és, s'escriuen just després. Amb Ctrl + Z es desfà.|Los fragmentos se escriben donde está el cursor: tocad primero el sitio del código (el final de una línea, por ejemplo). Una forma o un mueve nunca van dentro de unos paréntesis: si el cursor está ahí, se escriben justo después. Con Ctrl + Z se deshace."]],
    extra: ['Repetir el dictat 3D amb instruccions en forma de codi: cub(2, 4, 1)…|Repetir el dictado 3D con instrucciones en forma de código: cubo(2, 4, 1)…', 'Exportar el disseny a .scad i obrir-lo amb OpenSCAD.|Exportar el diseño a .scad y abrirlo con OpenSCAD.', 'Fer el suport de l\'encàrrec en tres mides diferents.|Hacer el soporte del encargo en tres medidas distintas.'],
    trans: ['Sessió següent: cub, cilindre i esfera a fons (centrat i mides).|Sesión siguiente: cubo, cilindro y esfera a fondo (centrado y medidas).', 'Matemàtiques: coordenades i cossos geomètrics.|Matemáticas: coordenadas y cuerpos geométricos.'],
    slides: [
      { id: 's1', k: 'portada', t: 'Del ratolí al codi|Del ratón al código', x: 'Dissenyem en 3D amb instruccions|Diseñamos en 3D con instrucciones', nota: "Presenta l'estudi d'enginyeria i l'encàrrec dels 30 suports.|Presenta el estudio de ingeniería y el encargo de los 30 soportes." },
      { id: 's2', k: 'pregunta', t: 'Ratolí o codi?|¿Ratón o código?', x: 'Has de fer el mateix suport en 30 mides diferents. Com t\'hi posaries?|Tienes que hacer el mismo soporte en 30 medidas distintas. ¿Cómo lo harías?', nota: 'Recull idees. Busquem que surti la idea de «canviar un número».|Recoge ideas. Buscamos que salga la idea de «cambiar un número».' },
      { id: 's3', k: 'anim', t: 'El programa és la recepta|El programa es la receta', anim: 'm3recipe', x: "L'ordinador llegeix de dalt a baix.|El ordenador lee de arriba abajo.", nota: 'Llegeix cada línia en veu alta i assenyala la peça que fa.|Lee cada línea en voz alta y señala la pieza que hace.' },
      { id: 's4', k: 'media', t: 'cub(amplada, fondària, alçada)|cubo(anchura, fondo, altura)', media: { k: 'model', prog: 'cub(40, 20, 10)' }, nota: "Gira el model per veure la cantonada a l'origen, on es creuen les línies de la placa.|Gira el modelo para ver la esquina en el origen, donde se cruzan las líneas de la placa." },
      { id: 's5', k: 'media', t: 'Cilindre, esfera i con|Cilindro, esfera y cono', media: { k: 'model', prog: 'mou(-30, 0, 0) cilindre(16, 30)\nmou(0, 0, 10) esfera(20)\nmou(30, 0, 0) con(20, 30)' }, nota: "Pregunta per què l'esfera té un mou(0, 0, 10). Resposta: té el centre a l'origen.|Pregunta por qué la esfera tiene un mueve(0, 0, 10). Respuesta: tiene el centro en el origen." },
      { id: 's6', k: 'media', t: 'mou(x, y, z)|mueve(x, y, z)', media: { k: 'model', prog: 'cub(20)\nmou(30, 0, 0) cub(20)' }, nota: 'Abans de mostrar el model, demana que prediguin on quedarà el segon cub.|Antes de mostrar el modelo, pide que predigan dónde quedará el segundo cubo.' },
      { id: 's7', k: 'concepte', t: 'Per què amb codi?|¿Por qué con código?', x: 'Precís (mil·límetres exactes), repetible (el programa es pot tornar a fer servir) i fàcil de canviar (un número).|Preciso (milímetros exactos), repetible (el programa se puede volver a usar) y fácil de cambiar (un número).', nota: "Connecta amb l'encàrrec dels 30 suports.|Conecta con el encargo de los 30 soportes." },
      { id: 's8', k: 'activitat', t: 'El dictat 3D|El dictado 3D', timer: 8, punts: ['Construeix una figura de 4 peces amagada.|Construye una figura de 4 piezas escondida.', 'Escriu les instruccions en ordre.|Escribe las instrucciones en orden.', "L'altra persona la fa sense mirar.|La otra persona la hace sin mirar."], nota: "Per parelles. Al final, que comptin quantes instruccions eren ambigües.|Por parejas. Al final, que cuenten cuántas instrucciones eran ambiguas." },
      { id: 's9', k: 'repte', t: "A l'ordinador|En el ordenador", punts: ['Prediu quin model fa cada programa.|Predice qué modelo hace cada programa.', 'Fes un cub de 30 mm i una base.|Haz un cubo de 30 mm y una base.', "Posa l'esfera a sobre del cub i fes la torre.|Pon la esfera encima del cubo y haz la torre."], nota: 'El primer repte, amb blocs; la resta, a la pestanya Codi: un fragment escriu la instrucció i només cal canviar-ne els números.|El primer reto, con bloques; el resto, en la pestaña Código: un fragmento escribe la instrucción y solo hay que cambiar sus números.' },
      { id: 's10', k: 'media', t: "L'esfera a sobre del cub|La esfera encima del cubo", media: { k: 'model', prog: 'cub(20)\nmou(10, 10, 30) esfera(20)' }, nota: "Per a qui s'encalli: x i y = 10 (el centre del cub); z = 20 (on acaba el cub) + 10 (el radi).|Para quien se atasque: x e y = 10 (el centro del cubo); z = 20 (donde acaba el cubo) + 10 (el radio)." },
      { id: 's11', k: 'media', t: 'La torre|La torre', media: { k: 'model', prog: 'cilindre(20, 40)\nmou(0, 0, 40) con(26, 15)' }, nota: 'El con comença on acaba el cilindre: 40 mm amunt.|El cono empieza donde acaba el cilindro: 40 mm hacia arriba.' },
      { id: 's12', k: 'repte', t: 'El teu primer disseny amb codi|Tu primer diseño con código', punts: ['Almenys 3 formes.|Al menos 3 formas.', 'Fes servir mou.|Usa mueve.', 'Tot toca la placa o una altra forma.|Todo toca la placa u otra forma.'], nota: 'Disseny lliure. Es desa a «Projectes».|Diseño libre. Se guarda en «Proyectos».' },
      { id: 's13', k: 'resum', t: 'Avui hem après…|Hoy hemos aprendido…', punts: ['Un programa 3D és una recepta.|Un programa 3D es una receta.', "Cada forma té el seu punt de referència a l'origen.|Cada forma tiene su punto de referencia en el origen.", 'mou col·loca la forma que ve després.|mueve coloca la forma que viene después.'], nota: 'Llegiu-ho junts.|Leedlo juntos.' },
      { id: 's14', k: 'tiquet', t: 'Tiquet de sortida|Ticket de salida', punts: ['Què fa mou(0, 0, 20)?|¿Qué hace mueve(0, 0, 20)?', 'Escriu un cub de 40 × 20 × 10 mm.|Escribe un cubo de 40 × 20 × 10 mm.'], nota: 'En un paper, abans de sortir.|En un papel, antes de salir.' }
    ],
    print: [{ id: 'p1', t: 'Fitxa: llegeix el programa|Ficha: lee el programa', k: 'fitxa', intro: 'Llegeix cada programa i respon. Recorda: x, y, z en mil·límetres.|Lee cada programa y responde. Recuerda: x, y, z en milímetros.',
      items: [{ q: 'Quines mides té cub(40, 20, 10)?|¿Qué medidas tiene cubo(40, 20, 10)?', sol: '40 mm d\'amplada, 20 de fondària i 10 d\'alçada.|40 mm de anchura, 20 de fondo y 10 de altura.' }, { q: 'On queda la cantonada del cub?|¿Dónde queda la esquina del cubo?', sol: "A l'origen (0, 0, 0).|En el origen (0, 0, 0)." },
        { q: 'Una esfera de 20 mm ha de quedar just a sobre de la placa. Quin mou li cal?|Una esfera de 20 mm tiene que quedar justo encima de la placa. ¿Qué mueve le hace falta?', sol: 'mou(0, 0, 10): el centre a 10 mm d\'alçada.|mueve(0, 0, 10): el centro a 10 mm de altura.' }] }]
  },
  /* ---------- Sessió 2 · Cub, cilindre i esfera ---------- */
  'p1-2': {
    obj: ["L'alumne/a indica el punt de referència de cada forma (cantonada, centre de la base o centre) i calcula on acaba.|El alumno/a indica el punto de referencia de cada forma (esquina, centro de la base o centro) y calcula dónde acaba.", "L'alumne/a fa servir «centrat» i el compensa amb un mou de la meitat de l'alçada perquè la peça recolzi a la placa.|El alumno/a usa «centrado» y lo compensa con un mueve de la mitad de la altura para que la pieza se apoye en la placa.",
      "L'alumne/a distingeix el diàmetre del radi i passa d'una fitxa tècnica amb radis a instruccions amb diàmetres.|El alumno/a distingue el diámetro del radio y pasa de una ficha técnica con radios a instrucciones con diámetros.", "L'alumne/a fa troncs de con amb el tercer paràmetre de con.|El alumno/a hace troncos de cono con el tercer parámetro de cono."],
    comp: ['Tecnologia i digitalització: CAD 3D amb paràmetres i especificacions tècniques|Tecnología y digitalización: CAD 3D con parámetros y especificaciones técnicas', 'Matemàtiques: cossos geomètrics (prisma, cilindre, esfera, con i tronc de con), radi i diàmetre|Matemáticas: cuerpos geométricos (prisma, cilindro, esfera, cono y tronco de cono), radio y diámetro', 'Matemàtiques: mesura en mil·límetres i coordenades en l\'espai|Matemáticas: medida en milímetros y coordenadas en el espacio', 'Pensament computacional: paràmetres d\'una instrucció i valors per defecte|Pensamiento computacional: parámetros de una instrucción y valores por defecto'],
    vocab: [['Punt de referència|Punto de referencia', "El punt de la forma que queda a l'origen quan no hi ha cap mou.|El punto de la forma que queda en el origen cuando no hay ningún mueve."], ['Centrat|Centrado', "Opció que posa el centre de la forma a l'origen.|Opción que pone el centro de la forma en el origen."], ['Diàmetre|Diámetro', "L'amplada d'un cercle passant pel centre: el doble del radi.|La anchura de un círculo pasando por el centro: el doble del radio."], ['Radi|Radio', 'La distància del centre del cercle a la vora.|La distancia del centro del círculo al borde.'], ['Tronc de con|Tronco de cono', 'Un con tallat per dalt: té un diàmetre a baix i un altre a dalt.|Un cono cortado por arriba: tiene un diámetro abajo y otro arriba.'], ['Fitxa tècnica|Ficha técnica', "Document amb les mides exactes que ha de tenir una peça.|Documento con las medidas exactas que tiene que tener una pieza."]],
    mat: { aula: ["Un ordinador per alumne/a amb Numi Tech obert a la sessió «Cub, cilindre i esfera»|Un ordenador por alumno/a con Numi Tech abierto en la sesión «Cubo, cilindro y esfera»", 'Projector i la presentació de la sessió|Proyector y la presentación de la sesión', "Per grup de tres: un regle (o un peu de rei), gomets i tres objectes de l'aula amb formes simples (un dau, un tub de cola, una pilota petita)|Por grupo de tres: una regla (o un pie de rey), gomets y tres objetos del aula con formas simples (un dado, un tubo de pegamento, una pelota pequeña)"],
      imprimir: ['Fitxa: la fitxa tècnica (una per grup)|Ficha: la ficha técnica (una por grupo)', 'Fitxa: on acaba cada forma? (una per alumne/a)|Ficha: ¿dónde acaba cada forma? (una por alumno/a)'], prep: ['Preparar els objectes per grups i comprovar que es poden mesurar amb el regle.|Preparar los objetos por grupos y comprobar que se pueden medir con la regla.', "Provar el repte del cilindre de la fitxa: és el que fa caure més alumnes en l'error del radi.|Probar el reto del cilindro de la ficha: es el que hace caer a más alumnos en el error del radio.", "Tenir a mà un objecte rodó gran (un got) per ensenyar el diàmetre i el radi amb el regle.|Tener a mano un objeto redondo grande (un vaso) para enseñar el diámetro y el radio con la regla."] },
    plan: [
      { min: 5, t: "L'encàrrec del museu|El encargo del museo", fase: 'inici', fa: "Presenta l'encàrrec del kit de sòlids: quatre peces amb mides exactes que han de cabre a les vitrines. Pregunta quins números caldrien per fabricar un dau i una pilota.|Presenta el encargo del kit de sólidos: cuatro piezas con medidas exactas que tienen que caber en las vitrinas. Pregunta qué números harían falta para fabricar un dado y una pelota.",
        diu: ['Quins números necessita la impressora per fer un dau? I una pilota?|¿Qué números necesita la impresora para hacer un dado? ¿Y una pelota?'], slides: ['s1', 's2'], app: 'Encara no: pantalles abaixades.|Todavía no: pantallas bajadas.', org: 'Tot el grup|Todo el grupo' },
      { min: 13, t: 'On neix cada forma|Dónde nace cada forma', fase: 'teoria', fa: "Presenta el punt de referència de cada forma amb l'animació i comproveu-ho als models 3D. Treballa «centrat» amb un exemple: on queda el cub i com es puja. Ensenya el diàmetre i el radi amb un got de veritat i el regle. Acaba amb el con de tres números.|Presenta el punto de referencia de cada forma con la animación y comprobadlo en los modelos 3D. Trabaja «centrado» con un ejemplo: dónde queda el cubo y cómo se sube. Enseña el diámetro y el radio con un vaso de verdad y la regla. Acaba con el cono de tres números.",
        diu: ["On és l'origen en aquest cub? I en el cilindre?|¿Dónde está el origen en este cubo? ¿Y en el cilindro?", "Si un cub centrat fa 30 mm, quant l'he de pujar?|Si un cubo centrado mide 30 mm, ¿cuánto tengo que subirlo?", 'Aquest got fa 80 mm de diàmetre. Quin és el radi?|Este vaso mide 80 mm de diámetro. ¿Cuál es el radio?'], slides: ['s3', 's4', 's5', 's6', 's7', 's8', 's9'], app: "Encara no: tota l'atenció a la projecció.|Todavía no: toda la atención en la proyección.", org: 'Tot el grup|Todo el grupo' },
      { min: 10, t: 'La fitxa tècnica|La ficha técnica', fase: 'desconnectat', fa: "En grups de tres, mesuren tres objectes reals, n'escriuen la instrucció i marquen el punt de referència amb un gomet. Després intercanvien les fitxes amb un altre grup, que ha d'endevinar quin objecte és cada instrucció.|En grupos de tres, miden tres objetos reales, escriben su instrucción y marcan el punto de referencia con un gomet. Después intercambian las fichas con otro grupo, que tiene que adivinar qué objeto es cada instrucción.",
        diu: ['On mesureu el diàmetre? Per què pel centre?|¿Dónde medís el diámetro? ¿Por qué por el centro?', 'On aniria el gomet si la peça fos centrada?|¿Dónde iría el gomet si la pieza estuviera centrada?'], slides: ['s10'], app: 'Encara no: regles i objectes.|Todavía no: reglas y objetos.', org: 'Grups de tres|Grupos de tres' },
      { min: 22, t: "A l'ordinador: el kit de sòlids|En el ordenador: el kit de sólidos", fase: 'ordinador', fa: "Fan la sessió a l'app: prediccions, dos errors per trobar i les quatre peces del kit. Al repte del cilindre, abans d'ajudar pregunta què diu la fitxa: el radi o el diàmetre? El repte de la peanya és opcional per a qui acabi abans.|Hacen la sesión en la app: predicciones, dos errores por encontrar y las cuatro piezas del kit. En el reto del cilindro, antes de ayudar pregunta qué dice la ficha: ¿el radio o el diámetro? El reto de la peana es opcional para quien acabe antes.",
        diu: ["On és el centre d'aquesta esfera? A quina alçada ha d'anar?|¿Dónde está el centro de esta esfera? ¿A qué altura tiene que ir?", 'La fitxa et dona el radi o el diàmetre?|¿La ficha te da el radio o el diámetro?'], slides: ['s11', 's12', 's13'], app: 'Sessió «Cub, cilindre i esfera», fins a «La teva peça per al museu».|Sesión «Cubo, cilindro y esfera», hasta «Tu pieza para el museo».', org: 'Individual|Individual' },
      { min: 5, t: 'La peça per al museu|La pieza para el museo', fase: 'crea', fa: "Disseny lliure d'una escultura geomètrica amb almenys tres formes, algun «centrat» ben col·locat i algun con o tronc de con. Es desa a «Projectes».|Diseño libre de una escultura geométrica con al menos tres formas, algún «centrado» bien colocado y algún cono o tronco de cono. Se guarda en «Proyectos».",
        diu: ['Quina peça és centrada? Com has calculat la z del seu mou?|¿Qué pieza está centrada? ¿Cómo has calculado la z de su mueve?'], slides: ['s14'], app: 'Pas «La teva peça per al museu».|Paso «Tu pieza para el museo».', org: 'Individual|Individual' },
      { min: 5, t: 'Tancament|Cierre', fase: 'tancament', fa: 'Repassa les tres idees clau i fes el tiquet de sortida.|Repasa las tres ideas clave y haz el ticket de salida.', diu: ['On queda un cub centrat sense mou? Què escrius si la fitxa diu radi 5?|¿Dónde queda un cubo centrado sin mueve? ¿Qué escribes si la ficha dice radio 5?'], slides: ['s15', 's16'], app: "Les últimes preguntes i «Com t'ha anat?».|Las últimas preguntas y «¿Cómo te ha ido?».", org: 'Tot el grup|Todo el grupo' }
    ],
    errors: [["Escriu el radi on va el diàmetre i el cilindre surt la meitat d'ample.|Escribe el radio donde va el diámetro y el cilindro sale la mitad de ancho.", "Que llegeixi la fitxa en veu alta i digui si el número és radi o diàmetre. Amb el regle i un objecte rodó, que mesuri tots dos.|Que lea la ficha en voz alta y diga si el número es radio o diámetro. Con la regla y un objeto redondo, que mida los dos."],
      ['Posa «centrat» i no entén per què la peça queda mig amagada.|Pone «centrado» y no entiende por qué la pieza queda medio escondida.', "Que giri la vista i la miri de costat: la meitat és sota la placa. El centre és a z = 0; cal pujar-la la meitat de l'alçada.|Que gire la vista y la mire de lado: la mitad está bajo la placa. El centro está en z = 0; hay que subirla la mitad de la altura."],
      ["Puja l'esfera tot el diàmetre en lloc de la meitat i queda flotant.|Sube la esfera todo el diámetro en lugar de la mitad y queda flotando.", "Recorda que l'esfera té el centre a l'origen: per tocar la placa, el centre ha d'estar a una distància d'un radi.|Recuerda que la esfera tiene el centro en el origen: para tocar la placa, el centro tiene que estar a una distancia de un radio."]],
    diff: { mes: "Fer el repte de la peanya i, després, una segona versió del kit a escala 1:2 (totes les mides a la meitat) recalculant tots els mou.|Hacer el reto de la peana y, después, una segunda versión del kit a escala 1:2 (todas las medidas a la mitad) recalculando todos los mueve.",
      menys: "Tenir a la vora la targeta dels punts de referència (cub: cantonada; cilindre i con: centre de la base; esfera: centre). Fer primer els reptes sense «centrat».|Tener cerca la tarjeta de los puntos de referencia (cubo: esquina; cilindro y cono: centro de la base; esfera: centro). Hacer primero los retos sin «centrado»." },
    aval: { ticket: ['On queda un cub(20, centrat) sense mou? Com el poses a sobre de la placa?|¿Dónde queda un cubo(20, centrado) sin mueve? ¿Cómo lo pones encima de la placa?', 'Escriu un cilindre de radi 6 mm i 15 mm d\'alçada.|Escribe un cilindro de radio 6 mm y 15 mm de altura.'],
      rubric: [['Punt de referència|Punto de referencia', 'Diu on neix cada forma i calcula on acaba.|Dice dónde nace cada forma y calcula dónde acaba.', 'Coneix el del cub, però dubta amb les formes rodones.|Conoce el del cubo, pero duda con las formas redondas.'],
        ['Centrat|Centrado', "Fa servir «centrat» i el compensa amb la meitat de l'alçada.|Usa «centrado» y lo compensa con la mitad de la altura.", 'Fa servir «centrat», però corregeix la z a prova i error.|Usa «centrado», pero corrige la z a prueba y error.'],
        ['Diàmetre i radi|Diámetro y radio', "Passa del radi al diàmetre sense errors.|Pasa del radio al diámetro sin errores.", 'Confon el radi i el diàmetre algunes vegades.|Confunde el radio y el diámetro algunas veces.']] },
    casa: "Busca a casa tres objectes amb forma de cub, cilindre i esfera. Mesura'ls amb un regle i escriu la instrucció de cadascun, amb el diàmetre de les formes rodones.|Busca en casa tres objetos con forma de cubo, cilindro y esfera. Mídelos con una regla y escribe la instrucción de cada uno, con el diámetro de las formas redondas.",
    intro: "Sessió de precisió: cada número d'una forma té un significat exacte i cada forma té el seu punt de referència. És la base de tot el curs: quan l'alumnat sap on neix i on acaba cada forma, col·locar-la deixa de ser prova i error.|Sesión de precisión: cada número de una forma tiene un significado exacto y cada forma tiene su punto de referencia. Es la base de todo el curso: cuando el alumnado sabe dónde nace y dónde acaba cada forma, colocarla deja de ser prueba y error.",
    claus: ["Cub: cantonada a l'origen. Cilindre i con: centre de la base. Esfera: centre.|Cubo: esquina en el origen. Cilindro y cono: centro de la base. Esfera: centro.", "«Centrat» posa el centre a l'origen: la meitat de la peça queda sota la placa.|«Centrado» pone el centro en el origen: la mitad de la pieza queda bajo la placa.", 'A les formes rodones sempre s\'escriu el diàmetre, que és el doble del radi.|En las formas redondas siempre se escribe el diámetro, que es el doble del radio.', 'El tercer número de con és el diàmetre de dalt: fa un tronc de con.|El tercer número de cono es el diámetro de arriba: hace un tronco de cono.'],
    prev: ['Haver fet la sessió «Del ratolí al codi».|Haber hecho la sesión «Del ratón al código».', 'Saber mesurar amb un regle en mil·límetres.|Saber medir con una regla en milímetros.', 'Saber què és el centre d\'un cercle.|Saber qué es el centro de un círculo.'],
    faq: [["Per què el cub no té el centre a l'origen, com l'esfera?|¿Por qué el cubo no tiene el centro en el origen, como la esfera?", "És el conveni d'OpenSCAD, que fan servir molts enginyers: així les mides d'una caixa coincideixen amb les coordenades de les cantonades. Si el voleu centrat, hi ha l'opció «centrat».|Es la convención de OpenSCAD, que usan muchos ingenieros: así las medidas de una caja coinciden con las coordenadas de las esquinas. Si lo queréis centrado, está la opción «centrado»."],
      ["A l'OpenSCAD de veritat també es posa el diàmetre?|¿En el OpenSCAD de verdad también se pone el diámetro?", "OpenSCAD accepta el radi (r) o el diàmetre (d). En exportar el .scad, l'app escriu sempre «d = …» perquè el model sigui idèntic.|OpenSCAD acepta el radio (r) o el diámetro (d). Al exportar el .scad, la app escribe siempre «d = …» para que el modelo sea idéntico."],
      ['Per què no surt res per sota de la placa a la impressora?|¿Por qué no sale nada por debajo de la placa en la impresora?', "Perquè la impressora comença a la placa: el que hi ha per sota no es pot imprimir. Per això el model ha de tocar la placa i no tenir res per sota.|Porque la impresora empieza en la placa: lo que hay por debajo no se puede imprimir. Por eso el modelo tiene que tocar la placa y no tener nada por debajo."]],
    tec: [["No es veu la part de la peça que queda sota la placa.|No se ve la parte de la pieza que queda bajo la placa.", 'Toqueu la cara Davant del cub de vistes (es veu de cara, a nivell de la placa) o feu servir les mesures (regle) per veure on comença.|Tocad la cara Delante del cubo de vistas (se ve de frente, a nivel de la placa) o usad las medidas (regla) para ver dónde empieza.'],
      ["No troben com afegir el tercer número al con.|No encuentran cómo añadir el tercer número al cono.", "El fragment «con(20, 30)» en té dos: abans del parèntesi de tancar, escriviu una coma i el tercer número, con(30, 40, 44).|El fragmento «cono(20, 30)» tiene dos: antes del paréntesis de cierre, escribid una coma y el tercer número, cono(30, 40, 44)."],
      ["L'opció «centrat» no s'activa.|La opción «centrado» no se activa.", "Al codi és una paraula més dins dels parèntesis, cub(20, centrat): amb el cursor just abans del parèntesi de tancar, toqueu el fragment «centrat». L'esfera no en necessita, perquè sempre és centrada.|En el código es una palabra más dentro de los paréntesis, cubo(20, centrado): con el cursor justo antes del paréntesis de cierre, tocad el fragmento «centrado». La esfera no lo necesita, porque siempre está centrada."]],
    seg: ['Els regles i peus de rei es passen tancats i no es fan servir com a punxons.|Las reglas y pies de rey se pasan cerrados y no se usan como punzones.', 'Pausa activa a mitja sessió: canviar de postura i descansar la vista de la pantalla.|Pausa activa a media sesión: cambiar de postura y descansar la vista de la pantalla.'],
    extra: ['Fer el kit a escala 1:2 i comparar els volums de les dues versions.|Hacer el kit a escala 1:2 y comparar los volúmenes de las dos versiones.', 'Buscar la fórmula del volum del cilindre i calcular el del cilindre del kit.|Buscar la fórmula del volumen del cilindro y calcular el del cilindro del kit.', 'Exportar el .scad d\'una peça i comprovar si hi apareix el diàmetre.|Exportar el .scad de una pieza y comprobar si aparece el diámetro.'],
    trans: ['Matemàtiques: cossos geomètrics, radi i diàmetre, longitud de la circumferència.|Matemáticas: cuerpos geométricos, radio y diámetro, longitud de la circunferencia.', "Sessió següent: llegir programes d'altres persones (PRIMM) i trobar-hi errors.|Sesión siguiente: leer programas de otras personas (PRIMM) y encontrar errores."],
    slides: [
      { id: 's1', k: 'portada', t: 'Cub, cilindre i esfera|Cubo, cilindro y esfera', x: 'Cada número té un significat exacte|Cada número tiene un significado exacto', nota: "Presenta l'encàrrec del museu: un kit de sòlids amb mides exactes.|Presenta el encargo del museo: un kit de sólidos con medidas exactas." },
      { id: 's2', k: 'pregunta', t: 'Quins números calen?|¿Qué números hacen falta?', x: "Has de fabricar un dau de 16 mm i una pilota de 30 mm per a una vitrina. Què li has de dir a la impressora?|Tienes que fabricar un dado de 16 mm y una pelota de 30 mm para una vitrina. ¿Qué le tienes que decir a la impresora?", nota: "Recull respostes: hi ha d'aparèixer la forma, les mides i on va.|Recoge respuestas: tienen que aparecer la forma, las medidas y dónde va." },
      { id: 's3', k: 'anim', t: 'On neix cada forma|Dónde nace cada forma', anim: 'p12ref', x: "El punt groc és l'origen (0, 0, 0).|El punto amarillo es el origen (0, 0, 0).", nota: 'Assenyala a cada forma on és el punt groc. Pregunta on acabarà cada forma.|Señala en cada forma dónde está el punto amarillo. Pregunta dónde acabará cada forma.' },
      { id: 's4', k: 'media', t: 'cub(amplada, fondària, alçada)|cubo(anchura, fondo, altura)', media: { k: 'model', prog: 'cub(40, 20, 10)\nmou(50, 0, 0) cub(20)' }, nota: "Gira el model: la caixa va de x = 0 a x = 40. Amb un sol número és un cub.|Gira el modelo: la caja va de x = 0 a x = 40. Con un solo número es un cubo." },
      { id: 's5', k: 'anim', t: "L'opció «centrat»|La opción «centrado»", anim: 'p12cen', x: "La meitat queda sota la placa: cal pujar-la la meitat de l'alçada.|La mitad queda bajo la placa: hay que subirla la mitad de la altura.", nota: 'Pregunta: si el cub fes 30 mm, quant l\'hauríem de pujar? (15 mm)|Pregunta: si el cubo midiera 30 mm, ¿cuánto tendríamos que subirlo? (15 mm)' },
      { id: 's6', k: 'media', t: 'Centrat i pujat|Centrado y subido', media: { k: 'model', prog: 'color("gris") cub(20, centrat)\nmou(30, 0, 10) cub(20, centrat)' }, code: 'cub(20, centrat)\nmou(30, 0, 10) cub(20, centrat)|cubo(20, centrado)\nmueve(30, 0, 10) cubo(20, centrado)', nota: "El cub gris és mig enfonsat; el rosa, pujat 10 mm, recolza a la placa.|El cubo gris está medio hundido; el rosa, subido 10 mm, se apoya en la placa." },
      { id: 's7', k: 'anim', t: 'Diàmetre i radi|Diámetro y radio', anim: 'p12diam', x: 'Al nostre llenguatge sempre s\'escriu el diàmetre.|En nuestro lenguaje siempre se escribe el diámetro.', nota: "Ensenya-ho amb un got i el regle: mesureu el diàmetre i el radi.|Enséñalo con un vaso y la regla: medid el diámetro y el radio." },
      { id: 's8', k: 'media', t: 'Cons i troncs de con|Conos y troncos de cono', media: { k: 'model', prog: 'con(30, 30)\nmou(40, 0, 0) con(30, 30, 14)\nmou(80, 0, 0) con(16, 30, 30)' }, nota: "El tercer número és el diàmetre de dalt. Si és més gran que el de baix, fa un got.|El tercer número es el diámetro de arriba. Si es mayor que el de abajo, hace un vaso." },
      { id: 's9', k: 'concepte', t: 'On acaba cada forma?|¿Dónde acaba cada forma?', punts: ['cub(30): de 0 a 30 en x, y i z|cubo(30): de 0 a 30 en x, y y z', 'cub(30, centrat): de −15 a 15|cubo(30, centrado): de −15 a 15', 'cilindre(30, 10): de −15 a 15 en x i y, de 0 a 10 en z|cilindro(30, 10): de −15 a 15 en x e y, de 0 a 10 en z', 'esfera(30): de −15 a 15 en tots els eixos|esfera(30): de −15 a 15 en todos los ejes'], anim: 'p12ref', nota: 'Fes-ho com a càlcul mental ràpid: la classe diu els números abans que apareguin.|Hazlo como cálculo mental rápido: la clase dice los números antes de que aparezcan.' },
      { id: 's10', k: 'activitat', t: 'La fitxa tècnica|La ficha técnica', timer: 8, punts: ['Mesureu tres objectes en mil·límetres.|Medid tres objetos en milímetros.', 'Escriviu la instrucció de cadascun.|Escribid la instrucción de cada uno.', 'Marqueu el punt de referència amb un gomet.|Marcad el punto de referencia con un gomet.', 'Intercanvieu les fitxes amb un altre grup.|Intercambiad las fichas con otro grupo.'], nota: 'Grups de tres amb la fitxa tècnica. Passa per les taules mirant com mesuren el diàmetre.|Grupos de tres con la ficha técnica. Pasa por las mesas mirando cómo miden el diámetro.' },
      { id: 's11', k: 'repte', t: "A l'ordinador: el kit de sòlids|En el ordenador: el kit de sólidos", punts: ['Prediu i troba els errors dels trofeus.|Predice y encuentra los errores de los trofeos.', 'Fes el dau, la pilota, el cilindre i el got.|Haz el dado, la pelota, el cilindro y el vaso.', 'Opcional: la peanya amb tot el kit.|Opcional: la peana con todo el kit.'], nota: "Recorda: abans de tocar números, pensa on és el punt de referència.|Recuerda: antes de tocar números, piensa dónde está el punto de referencia." },
      { id: 's12', k: 'media', t: 'El dau, sobre la placa|El dado, sobre la placa', media: { k: 'model', prog: 'mou(0, 0, 8) cub(16, centrat)' }, nota: "Per a qui s'encalli: un cub centrat de 16 mm es puja 8 mm.|Para quien se atasque: un cubo centrado de 16 mm se sube 8 mm." },
      { id: 's13', k: 'concepte', t: 'Radi o diàmetre?|¿Radio o diámetro?', x: 'La fitxa diu radi 12 mm: al cilindre hi va 2 × 12 = 24.|La ficha dice radio 12 mm: en el cilindro va 2 × 12 = 24.', code: 'mou(-40, 0, 0) cilindre(24, 30)|mueve(-40, 0, 0) cilindro(24, 30)', anim: 'p12diam', nota: "Projecta-ho quan vegis que diversos alumnes han posat 12.|Proyéctalo cuando veas que varios alumnos han puesto 12." },
      { id: 's14', k: 'repte', t: 'La teva peça per al museu|Tu pieza para el museo', punts: ['Almenys 3 formes.|Al menos 3 formas.', 'Algun «centrat» ben col·locat.|Algún «centrado» bien colocado.', 'Algun con o tronc de con.|Algún cono o tronco de cono.'], nota: 'Es desa a «Projectes». Qui vulgui, que n\'exporti el .scad.|Se guarda en «Proyectos». Quien quiera, que exporte el .scad.' },
      { id: 's15', k: 'resum', t: 'Avui hem après…|Hoy hemos aprendido…', punts: ["Cada forma té el seu punt de referència a l'origen.|Cada forma tiene su punto de referencia en el origen.", "«Centrat» posa el centre a l'origen: cal pujar la peça la meitat.|«Centrado» pone el centro en el origen: hay que subir la pieza la mitad.", 'A les formes rodones s\'escriu el diàmetre, el doble del radi.|En las formas redondas se escribe el diámetro, el doble del radio.'], nota: 'Llegiu-ho junts.|Leedlo juntos.' },
      { id: 's16', k: 'tiquet', t: 'Tiquet de sortida|Ticket de salida', punts: ['On queda un cub(20, centrat) sense mou?|¿Dónde queda un cubo(20, centrado) sin mueve?', "Escriu un cilindre de radi 6 mm i 15 mm d'alçada.|Escribe un cilindro de radio 6 mm y 15 mm de altura."], nota: 'En un paper, abans de sortir.|En un papel, antes de salir.' }
    ],
    print: [{ id: 'p1', t: 'Fitxa: la fitxa tècnica|Ficha: la ficha técnica', k: 'fitxa', intro: "Mesureu cada objecte en mil·límetres, escriviu-ne la instrucció i digueu on és el seu punt de referència.|Medid cada objeto en milímetros, escribid su instrucción y decid dónde está su punto de referencia.",
      items: [{ q: 'Objecte 1: nom, forma i mides (mm). Quina instrucció el fa?|Objeto 1: nombre, forma y medidas (mm). ¿Qué instrucción lo hace?', sol: 'Resposta oberta. Exemple: un dau de 16 mm → cub(16), punt de referència a una cantonada.|Respuesta abierta. Ejemplo: un dado de 16 mm → cubo(16), punto de referencia en una esquina.' },
        { q: 'Objecte 2: nom, forma i mides (mm). Quina instrucció el fa?|Objeto 2: nombre, forma y medidas (mm). ¿Qué instrucción lo hace?', sol: 'Resposta oberta. Exemple: un tub de cola de 20 mm de diàmetre i 90 d\'alt → cilindre(20, 90), centre de la base.|Respuesta abierta. Ejemplo: un tubo de pegamento de 20 mm de diámetro y 90 de alto → cilindro(20, 90), centro de la base.' },
        { q: 'Objecte 3: nom, forma i mides (mm). Quina instrucció el fa?|Objeto 3: nombre, forma y medidas (mm). ¿Qué instrucción lo hace?', sol: 'Resposta oberta. Exemple: una pilota de 40 mm → esfera(40), punt de referència al centre.|Respuesta abierta. Ejemplo: una pelota de 40 mm → esfera(40), punto de referencia en el centro.' },
        { q: "Una peça de la fitxa diu «radi 15 mm, alçada 8 mm». Quina instrucció escriuríeu?|Una pieza de la ficha dice «radio 15 mm, altura 8 mm». ¿Qué instrucción escribiríais?", sol: 'cilindre(30, 8): el diàmetre és el doble del radi.|cilindro(30, 8): el diámetro es el doble del radio.' }] },
      { id: 'p2', t: 'Fitxa: on acaba cada forma?|Ficha: ¿dónde acaba cada forma?', k: 'fitxa', intro: "Per a cada instrucció, escriu entre quins valors va la forma en x i en z (en mil·límetres).|Para cada instrucción, escribe entre qué valores va la forma en x y en z (en milímetros).",
      items: [{ q: 'cub(30)|cubo(30)', sol: 'x: de 0 a 30 · z: de 0 a 30|x: de 0 a 30 · z: de 0 a 30' }, { q: 'cub(30, centrat)|cubo(30, centrado)', sol: 'x: de −15 a 15 · z: de −15 a 15 (la meitat sota la placa)|x: de −15 a 15 · z: de −15 a 15 (la mitad bajo la placa)' },
        { q: 'cilindre(30, 10)|cilindro(30, 10)', sol: 'x: de −15 a 15 · z: de 0 a 10|x: de −15 a 15 · z: de 0 a 10' }, { q: 'mou(0, 0, 15) esfera(30)|mueve(0, 0, 15) esfera(30)', sol: 'x: de −15 a 15 · z: de 0 a 30 (toca la placa)|x: de −15 a 15 · z: de 0 a 30 (toca la placa)' },
        { q: 'Quin mou necessita un cub(40, centrat) per recolzar a la placa?|¿Qué mueve necesita un cubo(40, centrado) para apoyarse en la placa?', sol: 'mou(0, 0, 20)|mueve(0, 0, 20)' }] }]
  },
  /* ---------- Sessió 3 · Llegir un programa 3D ---------- */
  'p1-3': {
    obj: ["L'alumne/a segueix les fases de llegir codi: predir, executar, investigar, modificar i crear.|El alumno/a sigue las fases de leer código: predecir, ejecutar, investigar, modificar y crear.", "L'alumne/a explica l'efecte d'un mou sobre una forma i sobre un bloc { }.|El alumno/a explica el efecto de un mueve sobre una forma y sobre un bloque { }.",
      "L'alumne/a localitza la instrucció que fa que un model no sigui el que es volia.|El alumno/a localiza la instrucción que hace que un modelo no sea el que se quería.", "L'alumne/a modifica un programa d'una altra persona per complir un requisit.|El alumno/a modifica un programa de otra persona para cumplir un requisito."],
    comp: ['Pensament computacional: llegir, depurar i modificar programes|Pensamiento computacional: leer, depurar y modificar programas', 'Tecnologia i digitalització: CAD 3D i verificació d\'un disseny|Tecnología y digitalización: CAD 3D y verificación de un diseño', 'Matemàtiques: coordenades i relacions entre mides|Matemáticas: coordenadas y relaciones entre medidas', 'Aprendre a aprendre: comparar el resultat amb la predicció|Aprender a aprender: comparar el resultado con la predicción'],
    vocab: [['Predir|Predecir', 'Dir què farà un programa abans d\'executar-lo.|Decir qué hará un programa antes de ejecutarlo.'], ['Executar|Ejecutar', "Fer que l'ordinador segueixi el programa.|Hacer que el ordenador siga el programa."], ['Error (bug)|Error (bug)', 'Una part del programa que fa una cosa diferent de la que volíem.|Una parte del programa que hace algo distinto de lo que queríamos.'], ['Depurar|Depurar', 'Buscar i arreglar els errors.|Buscar y arreglar los errores.'], ['Bloc { }|Bloque { }', 'Un grup d\'instruccions entre claus que es transformen juntes.|Un grupo de instrucciones entre llaves que se transforman juntas.']],
    mat: { aula: ["Un ordinador per alumne/a amb Numi Tech obert a la sessió «Llegir un programa 3D»|Un ordenador por alumno/a con Numi Tech abierto en la sesión «Leer un programa 3D»", 'Projector i la presentació de la sessió|Proyector y la presentación de la sesión', 'Llapis i la fitxa de paper isomètric (una per parella)|Lápices y la ficha de papel isométrico (una por pareja)'],
      imprimir: ['Fitxa: llegeix i dibuixa (paper isomètric)|Ficha: lee y dibuja (papel isométrico)'], prep: ["Imprimir la fitxa amb els dos programes i la quadrícula isomètrica.|Imprimir la ficha con los dos programas y la cuadrícula isométrica.", "Provar el repte de modificar el monument: cal canviar un sol número.|Probar el reto de modificar el monumento: hay que cambiar un solo número.", 'Tenir a punt el programa del monument a la pissarra per fer-lo junts.|Tener preparado el programa del monumento en la pizarra para hacerlo juntos.'] },
    plan: [
      { min: 5, t: 'Recordem les formes|Recordamos las formas', fase: 'inici', fa: "Repàs ràpid: què fa cada forma i on té el punt de referència. Presenta la Júlia i els seus programes a mig fer.|Repaso rápido: qué hace cada forma y dónde tiene el punto de referencia. Presenta a Júlia y sus programas a medio hacer.",
        diu: ["Què fa cilindre(10, 30)? I on queda?|¿Qué hace cilindro(10, 30)? ¿Y dónde queda?"], slides: ['s1', 's2'], app: 'Encara no: pantalles abaixades.|Todavía no: pantallas bajadas.', org: 'Tot el grup|Todo el grupo' },
      { min: 12, t: 'Llegir com un enginyer|Leer como un ingeniero', fase: 'teoria', fa: "Presenta les cinc fases (predir, executar, investigar, modificar, crear). Fes una predicció en grup amb el monument: que la diguin abans de mostrar el model. Explica els blocs { } amb l'exemple dels dos cubs.|Presenta las cinco fases (predecir, ejecutar, investigar, modificar, crear). Haz una predicción en grupo con el monumento: que la digan antes de mostrar el modelo. Explica los bloques { } con el ejemplo de los dos cubos.",
        diu: ['Abans de mirar: quantes peces té? On és la bola?|Antes de mirar: ¿cuántas piezas tiene? ¿Dónde está la bola?', 'Què es mou amb el mou: un cub o els dos?|¿Qué se mueve con el mueve: un cubo o los dos?'], slides: ['s3', 's4', 's5', 's6', 's7'], app: "Encara no: tota l'atenció a la projecció.|Todavía no: toda la atención en la proyección.", org: 'Tot el grup|Todo el grupo' },
      { min: 10, t: 'Llegeix i dibuixa|Lee y dibuja', fase: 'desconnectat', fa: "Per parelles: un llegeix un programa de la fitxa en veu alta, línia a línia, i l'altre dibuixa el model al paper isomètric. Canvien de paper amb el segon programa. Després ho comproven a l'app.|Por parejas: uno lee un programa de la ficha en voz alta, línea a línea, y el otro dibuja el modelo en el papel isométrico. Cambian de papel con el segundo programa. Después lo comprueban en la app.",
        diu: ['Dibuixeu primer la base i després el que va a sobre.|Dibujad primero la base y después lo que va encima.'], slides: ['s8'], app: 'Encara no: fitxa i llapis.|Todavía no: ficha y lápiz.', org: 'Per parelles|Por parejas' },
      { min: 22, t: "A l'ordinador: troba i arregla|En el ordenador: encuentra y arregla", fase: 'ordinador', fa: "Fan la sessió a l'app: prediccions, trobar la instrucció equivocada i modificar el monument. Als reptes de trobar l'error, demana que comparin el model amb el fantasma abans de tocar cap número.|Hacen la sesión en la app: predicciones, encontrar la instrucción equivocada y modificar el monumento. En los retos de encontrar el error, pide que comparen el modelo con el fantasma antes de tocar ningún número.",
        diu: ['On comença a ser diferent del fantasma?|¿Dónde empieza a ser distinto del fantasma?', 'Quin número caldria canviar? Per quin?|¿Qué número habría que cambiar? ¿Por cuál?'], slides: ['s9', 's10', 's11'], app: "Sessió «Llegir un programa 3D», fins a «Fes-lo teu».|Sesión «Leer un programa 3D», hasta «Hazlo tuyo».", org: 'Individual|Individual' },
      { min: 6, t: 'Fes-lo teu|Hazlo tuyo', fase: 'crea', fa: "Parteixen del monument i el modifiquen al seu gust: noves mides, formes o colors, que continuï sent una sola peça. Es desa al portafoli.|Parten del monumento y lo modifican a su gusto: nuevas medidas, formas o colores, que siga siendo una sola pieza. Se guarda en el portafolio.",
        diu: ['Quins números has canviat i per què?|¿Qué números has cambiado y por qué?'], slides: ['s12'], app: 'Pas «Fes-lo teu».|Paso «Hazlo tuyo».', org: 'Individual|Individual' },
      { min: 5, t: 'Tancament|Cierre', fase: 'tancament', fa: 'Repassa les fases de llegir codi i què fa un bloc { }. Tiquet de sortida.|Repasa las fases de leer código y qué hace un bloque { }. Ticket de salida.', diu: ["Què fas abans d'executar un programa que no coneixes?|¿Qué haces antes de ejecutar un programa que no conoces?"], slides: ['s13', 's14'], app: "Les últimes preguntes i «Com t'ha anat?».|Las últimas preguntas y «¿Cómo te ha ido?».", org: 'Tot el grup|Todo el grupo' }
    ],
    errors: [['Toca instruccions a l\'atzar per trobar l\'error.|Toca instrucciones al azar para encontrar el error.', "Demana que primer descrigui la diferència entre el model i el fantasma (què sobra, què falta, què és més alt) i després busqui quina línia fa aquella peça.|Pide que primero describa la diferencia entre el modelo y el fantasma (qué sobra, qué falta, qué es más alto) y después busque qué línea hace esa pieza."],
      ["Canvia la mida de l'esfera en lloc de la seva posició.|Cambia el tamaño de la esfera en lugar de su posición.", "Pregunta-li si la bola és massa gran o és en un lloc equivocat. Si és el lloc, el número és al mou.|Pregúntale si la bola es demasiado grande o está en un lugar equivocado. Si es el lugar, el número está en el mueve."],
      ['No entén per què el mou afecta dues formes.|No entiende por qué el mueve afecta a dos formas.', "Ensenya-li les claus: les dues formes són dins del mou, entre { i }. Que mogui la } una línia amunt perquè una forma quedi fora i miri què passa.|Enséñale las llaves: las dos formas están dentro del mueve, entre { y }. Que mueva la } una línea arriba para que una forma quede fuera y mire qué pasa."]],
    diff: { mes: "Escriure el programa d'un monument nou per a un company perquè el prediguin; afegir-hi un error a propòsit i que el trobin.|Escribir el programa de un monumento nuevo para un compañero para que lo predigan; añadirle un error a propósito y que lo encuentren.",
      menys: 'Treballar el monument línia a línia, amagant les altres línies amb un paper. Fer les prediccions en parella.|Trabajar el monumento línea a línea, tapando las otras líneas con un papel. Hacer las predicciones en pareja.' },
    aval: { ticket: ["Què fas abans d'executar un programa que no coneixes?|¿Qué haces antes de ejecutar un programa que no conoces?", 'Què mou un mou seguit d\'un bloc { }?|¿Qué mueve un mueve seguido de un bloque { }?'],
      rubric: [['Predir|Predecir', 'Prediu el model i ho justifica amb els números.|Predice el modelo y lo justifica con los números.', 'Prediu, però sense justificar-ho.|Predice, pero sin justificarlo.'],
        ['Trobar errors|Encontrar errores', "Compara amb l'objectiu i troba la línia que falla.|Compara con el objetivo y encuentra la línea que falla.", 'Troba l\'error provant, sense raonar-ho.|Encuentra el error probando, sin razonarlo.'],
        ['Modificar|Modificar', "Canvia el número just per complir el requisit.|Cambia el número justo para cumplir el requisito.", 'Ho aconsegueix canviant diversos números a prova i error.|Lo consigue cambiando varios números a prueba y error.']] },
    casa: "Escriu un programa curt (3 línies) d'un objecte de casa i dona'l a algú perquè el dibuixi. S'assembla al que pensaves?|Escribe un programa corto (3 líneas) de un objeto de casa y dáselo a alguien para que lo dibuje. ¿Se parece a lo que pensabas?",
    intro: "Sessió de lectura de codi: l'objectiu no és escriure molt, sinó entendre programes d'altres i justificar-ne els canvis. L'esquema predir-executar-investigar-modificar-crear es farà servir tot el curs.|Sesión de lectura de código: el objetivo no es escribir mucho, sino entender programas de otros y justificar sus cambios. El esquema predecir-ejecutar-investigar-modificar-crear se usará todo el curso.",
    claus: ["Abans d'executar, predir: així l'error es nota quan el resultat no coincideix.|Antes de ejecutar, predecir: así el error se nota cuando el resultado no coincide.", 'Un mou afecta la forma següent o tot el bloc { } que el segueix.|Un mueve afecta a la forma siguiente o a todo el bloque { } que le sigue.', "Hi ha errors que el programa avisa (amb la línia) i errors que només es veuen comparant el model amb l'objectiu.|Hay errores que el programa avisa (con la línea) y errores que solo se ven comparando el modelo con el objetivo.", 'Per modificar, es canvia el mínim necessari.|Para modificar, se cambia lo mínimo necesario.'],
    prev: ['Haver fet la sessió «Del ratolí al codi».|Haber hecho la sesión «Del ratón al código».', 'Conèixer cub, cilindre, esfera i mou.|Conocer cubo, cilindro, esfera y mueve.', "Saber llegir coordenades x, y, z.|Saber leer coordenadas x, y, z."],
    faq: [['I si el programa no té cap error però no m\'agrada el resultat?|¿Y si el programa no tiene ningún error pero no me gusta el resultado?', "Llavors no és un error del programa, sinó del disseny: es modifica igual, canviant els números.|Entonces no es un error del programa, sino del diseño: se modifica igual, cambiando los números."],
      ['Per què es diu «bug» a un error?|¿Por qué se llama «bug» a un error?', "És una paraula anglesa que vol dir «insecte». Als inicis de la informàtica es va fer servir per parlar de les falles de les màquines.|Es una palabra inglesa que quiere decir «insecto». En los inicios de la informática se usó para hablar de los fallos de las máquinas."],
      ["Es pot desfer un canvi?|¿Se puede deshacer un cambio?", "Sí: amb el botó de desfer o tornant a posar el número d'abans. Per això convé canviar d'un en un.|Sí: con el botón de deshacer o volviendo a poner el número de antes. Por eso conviene cambiar de uno en uno."]],
    tec: [['No es veu el fantasma.|No se ve el fantasma.', "El botó del fantasma (a dalt de la vista) l'amaga i el mostra.|El botón del fantasma (arriba de la vista) lo esconde y lo muestra."],
      ["Als reptes de trobar l'error, en tocar una instrucció s'obre un número.|En los retos de encontrar el error, al tocar una instrucción se abre un número.", "Aquests reptes es mostren en blocs: toqueu la part de color de la instrucció (la paraula), no els números blancs.|Estos retos se muestran en bloques: tocad la parte de color de la instrucción (la palabra), no los números blancos."],
      ['La barra vermella diu que hi ha un error.|La barra roja dice que hay un error.', "Llegiu-la: diu la línia i què passa, i el número de la línia es marca en vermell. Sovint és un parèntesi o una coma que falta.|Leedla: dice la línea y qué pasa, y el número de la línea se marca en rojo. A menudo es un paréntesis o una coma que falta."]],
    extra: ['Fer un «programa misteri» per a un company i que el predigui.|Hacer un «programa misterio» para un compañero y que lo prediga.', 'Afegir un error a propòsit al monument i que un company el trobi.|Añadir un error a propósito al monumento y que un compañero lo encuentre.', 'Exportar el monument a .scad i comparar les dues versions del programa.|Exportar el monumento a .scad y comparar las dos versiones del programa.'],
    trans: ['Sessió següent: projecte del monument.|Sesión siguiente: proyecto del monumento.', 'Llengua: llegir instruccions i textos tècnics amb atenció.|Lengua: leer instrucciones y textos técnicos con atención.'],
    slides: [
      { id: 's1', k: 'portada', t: 'Llegir un programa 3D|Leer un programa 3D', x: 'Predir, executar, investigar, modificar i crear|Predecir, ejecutar, investigar, modificar y crear', nota: 'Presenta la Júlia i els seus programes a mig fer.|Presenta a Júlia y sus programas a medio hacer.' },
      { id: 's2', k: 'repas', t: 'Recordem les formes|Recordamos las formas', punts: ["cub: cantonada a l'origen|cubo: esquina en el origen", 'cilindre i con: base a z = 0|cilindro y cono: base en z = 0', "esfera: centre a l'origen|esfera: centro en el origen"], nota: 'Pregunta exemples ràpids: on quedarà un cilindre(10, 30)?|Pregunta ejemplos rápidos: ¿dónde quedará un cilindro(10, 30)?' },
      { id: 's3', k: 'anim', t: 'Llegir com un enginyer|Leer como un ingeniero', anim: 'm3primm', nota: 'Les cinc fases es faran servir tot el curs.|Las cinco fases se usarán todo el curso.' },
      { id: 's4', k: 'pregunta', t: 'Prediu: com és el monument?|Predice: ¿cómo es el monumento?', x: 'cub(40, 40, 10) · mou(20, 20, 10) cilindre(20, 30) · mou(20, 20, 50) esfera(20)|cubo(40, 40, 10) · mueve(20, 20, 10) cilindro(20, 30) · mueve(20, 20, 50) esfera(20)', nota: 'Deixa que dibuixin la predicció a la llibreta abans de passar a la diapositiva següent.|Deja que dibujen la predicción en la libreta antes de pasar a la diapositiva siguiente.' },
      { id: 's5', k: 'media', t: 'El monument|El monumento', media: { k: 'model', prog: MON }, nota: 'Compareu-ho amb les prediccions. Qui ho havia encertat? Per què?|Comparadlo con las predicciones. ¿Quién lo había acertado? ¿Por qué?' },
      { id: 's6', k: 'media', t: 'Un mou per a un bloc { }|Un mueve para un bloque { }', media: { k: 'model', prog: 'mou(30, 0, 0) {\n  cub(20)\n  mou(10, 10, 30) esfera(20)\n}\ncub(20)' }, nota: "El cub i l'esfera de dins es mouen junts; el cub de fora, no.|El cubo y la esfera de dentro se mueven juntos; el cubo de fuera, no." },
      { id: 's7', k: 'concepte', t: 'Dos tipus d\'errors|Dos tipos de errores', x: "Els que el programa avisa (amb la línia) i els que només es veuen comparant el model amb el que volíem.|Los que el programa avisa (con la línea) y los que solo se ven comparando el modelo con lo que queríamos.", nota: "Avui treballarem sobretot els segons: el programa funciona però el model no és el bo.|Hoy trabajaremos sobre todo los segundos: el programa funciona pero el modelo no es el bueno." },
      { id: 's8', k: 'activitat', t: 'Llegeix i dibuixa|Lee y dibuja', timer: 8, punts: ['Llegeix el programa en veu alta.|Lee el programa en voz alta.', "L'altra persona el dibuixa.|La otra persona lo dibuja.", 'Canvieu i després comproveu-ho.|Cambiad y después comprobadlo.'], nota: 'Per parelles amb la fitxa.|Por parejas con la ficha.' },
      { id: 's9', k: 'repte', t: "A l'ordinador|En el ordenador", punts: ['Prediu i comprova.|Predice y comprueba.', 'Troba la instrucció equivocada.|Encuentra la instrucción equivocada.', 'Modifica el monument.|Modifica el monumento.'], nota: 'Recorda: primer comparar amb el fantasma, després tocar.|Recuerda: primero comparar con el fantasma, después tocar.' },
      { id: 's10', k: 'media', t: 'On és l\'error?|¿Dónde está el error?', media: { k: 'model', prog: 'cub(40, 40, 10)\nmou(20, 20, 10) cilindre(20, 30)\nmou(20, 20, 70) esfera(20)', target: MON }, nota: 'La bola flota: la z del seu mou és 70 i hauria de ser 50.|La bola flota: la z de su mueve es 70 y tendría que ser 50.' },
      { id: 's11', k: 'concepte', t: 'Modificar el mínim|Modificar lo mínimo', x: "Per arreglar-ho n'hi ha prou de canviar un número. Si en canvies molts, és difícil saber quin ho ha arreglat.|Para arreglarlo basta con cambiar un número. Si cambias muchos, es difícil saber cuál lo ha arreglado.", nota: 'Bona pràctica de depuració: un canvi cada vegada.|Buena práctica de depuración: un cambio cada vez.' },
      { id: 's12', k: 'repte', t: 'Fes-lo teu|Hazlo tuyo', punts: ['Parteix del monument.|Parte del monumento.', 'Canvia mides, formes o colors.|Cambia medidas, formas o colores.', 'Que sigui una sola peça.|Que sea una sola pieza.'], nota: 'Es desa a «Projectes».|Se guarda en «Proyectos».' },
      { id: 's13', k: 'resum', t: 'Avui hem après…|Hoy hemos aprendido…', punts: ['Predir abans d\'executar.|Predecir antes de ejecutar.', 'Un mou afecta la forma o el bloc { } següent.|Un mueve afecta a la forma o al bloque { } siguiente.', 'Per arreglar, comparar i canviar el mínim.|Para arreglar, comparar y cambiar lo mínimo.'], nota: 'Llegiu-ho junts.|Leedlo juntos.' },
      { id: 's14', k: 'tiquet', t: 'Tiquet de sortida|Ticket de salida', punts: ["Què fas abans d'executar un programa que no coneixes?|¿Qué haces antes de ejecutar un programa que no conoces?", 'Què mou un mou seguit d\'un bloc { }?|¿Qué mueve un mueve seguido de un bloque { }?'], nota: 'Oral o en un paper.|Oral o en un papel.' }
    ],
    print: [{ id: 'p1', t: 'Fitxa: llegeix i dibuixa|Ficha: lee y dibuja', k: 'fitxa', intro: 'Dibuixa al paper isomètric el model que fa cada programa.|Dibuja en el papel isométrico el modelo que hace cada programa.',
      items: [{ q: 'cub(40, 40, 10) · mou(20, 20, 10) cilindre(20, 30) · mou(20, 20, 50) esfera(20)|cubo(40, 40, 10) · mueve(20, 20, 10) cilindro(20, 30) · mueve(20, 20, 50) esfera(20)', sol: 'Una base quadrada, una columna al mig i una bola a dalt.|Una base cuadrada, una columna en el centro y una bola arriba.' },
        { q: 'cub(60, 20, 10) · mou(10, 10, 10) cub(20) · mou(30, 10, 10) cub(20)|cubo(60, 20, 10) · mueve(10, 10, 10) cubo(20) · mueve(30, 10, 10) cubo(20)', sol: 'Una placa llarga amb dos cubs a sobre, un al costat de l\'altre.|Una placa larga con dos cubos encima, uno al lado del otro.' }] }]
  },
  /* ---------- Sessió 4 · Projecte: el monument ---------- */
  'p1-4': {
    obj: ["L'alumne/a segueix les fases del procés tecnològic: encàrrec, esbós, programa, comprovació i millora.|El alumno/a sigue las fases del proceso tecnológico: encargo, boceto, programa, comprobación y mejora.", "L'alumne/a dibuixa l'alçat d'un objecte amb cotes en mil·límetres i el tradueix a un programa.|El alumno/a dibuja el alzado de un objeto con cotas en milímetros y lo traduce a un programa.",
      "L'alumne/a apila peces calculant la z de cada una com la suma de les alçades de sota.|El alumno/a apila piezas calculando la z de cada una como la suma de las alturas de abajo.", "L'alumne/a comprova que el seu model és una sola peça estable que cap en una caixa donada.|El alumno/a comprueba que su modelo es una sola pieza estable que cabe en una caja dada."],
    comp: ['Tecnologia i digitalització: procés tecnològic i disseny assistit per ordinador|Tecnología y digitalización: proceso tecnológico y diseño asistido por ordenador', 'Tecnologia i digitalització: expressió gràfica (alçat i cotes)|Tecnología y digitalización: expresión gráfica (alzado y cotas)', 'Matemàtiques: mesura, sumes d\'alçades i proporcions|Matemáticas: medida, sumas de alturas y proporciones', 'Emprenedoria i comunicació: presentar una proposta a un concurs|Emprendimiento y comunicación: presentar una propuesta a un concurso'],
    vocab: [['Procés tecnològic|Proceso tecnológico', "Les fases per resoldre un problema amb un objecte: entendre'l, dissenyar, construir, comprovar i millorar.|Las fases para resolver un problema con un objeto: entenderlo, diseñar, construir, comprobar y mejorar."], ['Alçat|Alzado', "El dibuix d'un objecte vist de cara.|El dibujo de un objeto visto de frente."], ['Cota|Cota', 'Una línia amb un número que indica una mida en un dibuix tècnic.|Una línea con un número que indica una medida en un dibujo técnico.'], ['Maqueta|Maqueta', "Un model a escala d'un objecte o d'un edifici.|Un modelo a escala de un objeto o de un edificio."], ['Estabilitat|Estabilidad', "La capacitat d'un objecte d'aguantar-se sense tombar-se; ajuda tenir una base ampla.|La capacidad de un objeto de aguantarse sin volcarse; ayuda tener una base ancha."]],
    mat: { aula: ["Un ordinador per alumne/a amb Numi Tech obert a la sessió «Projecte: el monument»|Un ordenador por alumno/a con Numi Tech abierto en la sesión «Proyecto: el monumento»", 'Projector i la presentació de la sessió|Proyector y la presentación de la sesión', "Llapis, goma i un regle per alumne/a|Lápiz, goma y una regla por alumno/a"],
      imprimir: ["Fitxa: l'esbós amb cotes (una per alumne/a, sobre paper quadriculat)|Ficha: el boceto con cotas (una por alumno/a, sobre papel cuadriculado)", 'Fitxa: la rúbrica del concurs (una per parella)|Ficha: la rúbrica del concurso (una por pareja)'], prep: ["Imprimir les fitxes; si n'hi ha, fer servir paper quadriculat de 5 mm i dir que cada quadre són 10 mm.|Imprimir las fichas; si hay, usar papel cuadriculado de 5 mm y decir que cada cuadro son 10 mm.", "Fer l'obelisc pas a pas abans de la classe per conèixer els números (8, 14, 74, 78).|Hacer el obelisco paso a paso antes de la clase para conocer los números (8, 14, 74, 78).", 'Si hi ha impressora 3D, deixar-la a punt per imprimir dos o tres monuments a la sessió següent.|Si hay impresora 3D, dejarla a punto para imprimir dos o tres monumentos en la sesión siguiente.'] },
    plan: [
      { min: 5, t: 'Les bases del concurs|Las bases del concurso', fase: 'inici', fa: "Presenta el concurs de l'Ajuntament i les tres condicions: cap en 100 × 100 × 120 mm, és una sola peça i s'aguanta dreta. Pregunta quins monuments coneixen i quines formes tenen.|Presenta el concurso del Ayuntamiento y las tres condiciones: cabe en 100 × 100 × 120 mm, es una sola pieza y se aguanta de pie. Pregunta qué monumentos conocen y qué formas tienen.",
        diu: ['Quines formes geomètriques veieu en un obelisc, en una font o en una estàtua?|¿Qué formas geométricas veis en un obelisco, en una fuente o en una estatua?'], slides: ['s1', 's2'], app: 'Encara no: pantalles abaixades.|Todavía no: pantallas bajadas.', org: 'Tot el grup|Todo el grupo' },
      { min: 10, t: "De l'encàrrec a la peça|Del encargo a la pieza", fase: 'teoria', fa: "Explica el procés tecnològic i com un esbós amb cotes es converteix en programa: una peça, una línia. Feu junts el càlcul de les z de l'obelisc (8, 14, 74) i explica per què la bola entra 2 mm. Acaba amb la llista de comprovacions.|Explica el proceso tecnológico y cómo un boceto con cotas se convierte en programa: una pieza, una línea. Haced juntos el cálculo de las z del obelisco (8, 14, 74) y explica por qué la bola entra 2 mm. Acaba con la lista de comprobaciones.",
        diu: ["Si la base fa 8 mm i el sòcol 6, on comença l'agulla?|Si la base mide 8 mm y el zócalo 6, ¿dónde empieza la aguja?", 'Què passaria si la bola només toqués la punta?|¿Qué pasaría si la bola solo tocara la punta?'], slides: ['s3', 's4', 's5', 's6', 's7'], app: "Encara no: tota l'atenció a la projecció.|Todavía no: toda la atención en la proyección.", org: 'Tot el grup|Todo el grupo' },
      { min: 10, t: "L'esbós amb cotes|El boceto con cotas", fase: 'desconnectat', fa: "Cada alumne/a dibuixa l'alçat del seu monument a la fitxa, amb cotes i amb la z on comença cada peça. Després l'ensenya a un company/a, que comprova si s'entén i si cap a la caixa.|Cada alumno/a dibuja el alzado de su monumento en la ficha, con cotas y con la z donde empieza cada pieza. Después lo enseña a un compañero/a, que comprueba si se entiende y si cabe en la caja.",
        diu: ["Quina és la peça més ampla? És la base?|¿Cuál es la pieza más ancha? ¿Es la base?", "Quant fa d'alt en total? Cap en 120 mm?|¿Cuánto mide de alto en total? ¿Cabe en 120 mm?"], slides: ['s8', 's9'], app: 'Encara no: fitxa i llapis.|Todavía no: ficha y lápiz.', org: 'Individual i per parelles|Individual y por parejas' },
      { min: 18, t: "A l'ordinador: l'obelisc pas a pas|En el ordenador: el obelisco paso a paso", fase: 'ordinador', fa: "Fan la sessió a l'app: la predicció, dues propostes amb errors i l'obelisc en quatre passos amb fantasma. Qui acabi abans pot fer l'obelisc de 110 mm. Vigila que no passin al disseny lliure sense haver fet els quatre passos.|Hacen la sesión en la app: la predicción, dos propuestas con errores y el obelisco en cuatro pasos con fantasma. Quien acabe antes puede hacer el obelisco de 110 mm. Vigila que no pasen al diseño libre sin haber hecho los cuatro pasos.",
        diu: ['On acaba la peça de sota? Aquesta és la z.|¿Dónde acaba la pieza de abajo? Esa es la z.', "Mireu-ho de costat: hi ha algun buit?|Miradlo de lado: ¿hay algún hueco?"], slides: ['s10', 's11', 's12'], app: "Sessió «Projecte: el monument», fins a «El teu monument per al concurs».|Sesión «Proyecto: el monumento», hasta «Tu monumento para el concurso».", org: 'Individual|Individual' },
      { min: 12, t: 'El teu monument|Tu monumento', fase: 'crea', fa: "Programen el monument del seu esbós. L'app marca en directe les condicions del concurs. Quan les compleixen totes, el desen a «Projectes» amb un nom.|Programan el monumento de su boceto. La app marca en directo las condiciones del concurso. Cuando las cumplen todas, lo guardan en «Proyectos» con un nombre.",
        diu: ["Quina condició et falta? Quina línia l'arregla?|¿Qué condición te falta? ¿Qué línea la arregla?", "S'assembla al teu esbós? Què has canviat i per què?|¿Se parece a tu boceto? ¿Qué has cambiado y por qué?"], slides: ['s13'], app: 'Pas «El teu monument per al concurs».|Paso «Tu monumento para el concurso».', org: 'Individual|Individual' },
      { min: 5, t: 'La galeria del concurs|La galería del concurso', fase: 'tancament', fa: "Dos o tres alumnes presenten el seu monument: les mides, la base i què han millorat. La resta en valora un amb la rúbrica. Tanca amb les idees clau i el tiquet.|Dos o tres alumnos presentan su monumento: las medidas, la base y qué han mejorado. El resto valora uno con la rúbrica. Cierra con las ideas clave y el ticket.",
        diu: ['Què has hagut de canviar respecte de l\'esbós?|¿Qué has tenido que cambiar respecto del boceto?'], slides: ['s14', 's15', 's16'], app: "Les últimes preguntes i «Com t'ha anat?».|Las últimas preguntas y «¿Cómo te ha ido?».", org: 'Tot el grup|Todo el grupo' }
    ],
    errors: [["Posa cada peça a la z de l'alçada de la de sota, no a la suma de totes les de sota.|Pone cada pieza en la z de la altura de la de abajo, no en la suma de todas las de abajo.", "Que escrigui al costat de cada línia «comença a … i acaba a …». La z d'una peça és on acaba l'anterior.|Que escriba al lado de cada línea «empieza en … y acaba en …». La z de una pieza es donde acaba la anterior."],
      ["L'app diu que no és una sola peça, però sembla tot junt.|La app dice que no es una sola pieza, pero parece todo junto.", "Hi ha peces que només es toquen en un punt o que tenen un buit petit. Que miri de costat i faci que les peces s'encastin 1 o 2 mm.|Hay piezas que solo se tocan en un punto o que tienen un hueco pequeño. Que mire de lado y haga que las piezas se encajen 1 o 2 mm."],
      ['El monument no cap a la caixa del concurs.|El monumento no cabe en la caja del concurso.', "Que miri quina mida passa (amplada o alçada) amb el regle de mesures i ajusti una sola peça cada vegada.|Que mire qué medida se pasa (anchura o altura) con la regla de medidas y ajuste una sola pieza cada vez."]],
    diff: { mes: "Afegir-hi detalls amb colors i fer una segona versió del monument a escala 1:2. Explicar per escrit una millora feta després d'una comprovació.|Añadirle detalles con colores y hacer una segunda versión del monumento a escala 1:2. Explicar por escrito una mejora hecha después de una comprobación.",
      menys: "Partir de l'obelisc i canviar-hi peces una a una (per exemple, la bola per un con). Fer l'esbós amb només tres peces.|Partir del obelisco y cambiar piezas una a una (por ejemplo, la bola por un cono). Hacer el boceto con solo tres piezas." },
    aval: { ticket: ['Una base fa 8 mm i a sobre hi ha una columna de 30 mm. On comença la peça següent?|Una base mide 8 mm y encima hay una columna de 30 mm. ¿Dónde empieza la pieza siguiente?', "Digues una condició que ha de complir una maqueta abans d'imprimir-la.|Di una condición que tiene que cumplir una maqueta antes de imprimirla."],
      rubric: [['Esbós amb cotes|Boceto con cotas', "L'alçat té totes les cotes i la z de cada peça.|El alzado tiene todas las cotas y la z de cada pieza.", 'L\'alçat té peces sense cotes o sense z.|El alzado tiene piezas sin cotas o sin z.'],
        ['Modelatge|Modelado', 'Apila les peces calculant les z i les encasta perquè sigui una sola peça.|Apila las piezas calculando las z y las encaja para que sea una sola pieza.', 'Apila les peces a prova i error, amb algun buit.|Apila las piezas a prueba y error, con algún hueco.'],
        ['Condicions del concurs|Condiciones del concurso', 'Compleix totes les condicions i explica com les ha comprovat.|Cumple todas las condiciones y explica cómo las ha comprobado.', 'En compleix algunes amb ajuda.|Cumple algunas con ayuda.']] },
    casa: "Busca un monument del teu poble o ciutat (o una foto) i descompon-lo en formes geomètriques. Escriu-ne les mides aproximades i les peces en ordre, de baix a dalt.|Busca un monumento de tu pueblo o ciudad (o una foto) y descomponlo en formas geométricas. Escribe sus medidas aproximadas y las piezas en orden, de abajo arriba.",
    intro: "Primer projecte del nivell 2. L'alumnat aplica tot el que sap de formes i mou en un encàrrec amb condicions, seguint el procés tecnològic. És important dedicar temps de veritat a l'esbós amb cotes: és el que fa que el programa surti a la primera.|Primer proyecto del nivel 2. El alumnado aplica todo lo que sabe de formas y mueve en un encargo con condiciones, siguiendo el proceso tecnológico. Es importante dedicar tiempo de verdad al boceto con cotas: es lo que hace que el programa salga a la primera.",
    claus: ["El procés tecnològic: encàrrec, esbós, programa, comprovació, millora i fabricació.|El proceso tecnológico: encargo, boceto, programa, comprobación, mejora y fabricación.", "La z d'una peça apilada és la suma de les alçades de sota.|La z de una pieza apilada es la suma de las alturas de abajo.", "Les peces s'han d'encastar una mica per formar una sola peça.|Las piezas se tienen que encajar un poco para formar una sola pieza.", "Una base ampla fa el monument estable.|Una base ancha hace el monumento estable."],
    prev: ['Conèixer cub, cilindre, esfera i con, amb «centrat» i el tercer número del con.|Conocer cubo, cilindro, esfera y cono, con «centrado» y el tercer número del cono.', 'Saber fer servir mou per col·locar formes.|Saber usar mueve para colocar formas.', 'Saber llegir un programa curt i trobar-hi un error.|Saber leer un programa corto y encontrar un error.'],
    faq: [['Puc fer un monument que no sigui simètric?|¿Puedo hacer un monumento que no sea simétrico?', "Sí, sempre que s'aguanti dret: el centre de les peces de dalt ha de quedar a sobre de la base.|Sí, siempre que se aguante de pie: el centro de las piezas de arriba tiene que quedar encima de la base."],
      ["Per què ha de cabre en 100 × 100 × 120 mm?|¿Por qué tiene que caber en 100 × 100 × 120 mm?", "És la condició del concurs, com passa als encàrrecs reals: la mida de la vitrina, del paquet o de la impressora limiten el disseny.|Es la condición del concurso, como pasa en los encargos reales: la medida de la vitrina, del paquete o de la impresora limitan el diseño."],
      ["Es pot imprimir de veritat?|¿Se puede imprimir de verdad?", "Sí: des de «Projectes» es descarrega l'STL. Si el monument té peces que sobresurten molt, potser caldran suports a la impressora (ho veurem a la unitat 7).|Sí: desde «Proyectos» se descarga el STL. Si el monumento tiene piezas que sobresalen mucho, quizá harán falta soportes en la impresora (lo veremos en la unidad 7)."]],
    tec: [["El botó per desar no s'activa.|El botón para guardar no se activa.", "Encara falta alguna condició: mireu la llista de comprovacions de sota la vista 3D; les que no es compleixen no tenen la marca verda.|Todavía falta alguna condición: mirad la lista de comprobaciones de debajo de la vista 3D; las que no se cumplen no tienen la marca verde."],
      ["No es veu si hi ha un buit entre dues peces.|No se ve si hay un hueco entre dos piezas.", 'Feu servir la vista frontal i apropeu-vos amb dos dits o la roda del ratolí.|Usad la vista frontal y acercaos con dos dedos o la rueda del ratón.'],
      ["Ha esborrat el programa sense voler.|Ha borrado el programa sin querer.", "Amb el botó de desfer es recupera. Si ja ha sortit del pas, el pot tornar a obrir i partir de l'obelisc.|Con el botón de deshacer se recupera. Si ya ha salido del paso, puede volver a abrirlo y partir del obelisco."]],
    seg: ["Si s'imprimeix algun monument, la impressora només la manipula el professorat: el capçal i la placa cremen.|Si se imprime algún monumento, la impresora solo la manipula el profesorado: el cabezal y la placa queman.", 'A la galeria, es comenta el disseny, no la persona: primer una cosa ben feta i després una millora.|En la galería, se comenta el diseño, no la persona: primero algo bien hecho y después una mejora.'],
    extra: ['Imprimir els tres monuments més votats i fer-ne una petita exposició.|Imprimir los tres monumentos más votados y hacer una pequeña exposición.', 'Calcular quant plàstic gasta el monument (volum en cm³) i fer una versió que en gasti menys.|Calcular cuánto plástico gasta el monumento (volumen en cm³) y hacer una versión que gaste menos.', 'Fer la planta (vista de dalt) del monument amb cotes.|Hacer la planta (vista de arriba) del monumento con cotas.'],
    trans: ['Tecnologia: expressió gràfica (alçat, planta i perfil) i procés tecnològic.|Tecnología: expresión gráfica (alzado, planta y perfil) y proceso tecnológico.', 'Unitat següent: transformacions (moure i girar) per fer la maqueta del molí.|Unidad siguiente: transformaciones (mover y girar) para hacer la maqueta del molino.'],
    slides: [
      { id: 's1', k: 'portada', t: 'Projecte: el monument|Proyecto: el monumento', x: "Del concurs de la plaça a la maqueta impresa|Del concurso de la plaza a la maqueta impresa", nota: "Presenta el concurs de l'Ajuntament i el procés que seguirem.|Presenta el concurso del Ayuntamiento y el proceso que seguiremos." },
      { id: 's2', k: 'pregunta', t: 'Les bases del concurs|Las bases del concurso', punts: ['Cap en una caixa de 100 × 100 × 120 mm.|Cabe en una caja de 100 × 100 × 120 mm.', 'És una sola peça.|Es una sola pieza.', "S'aguanta dreta sobre una base.|Se aguanta de pie sobre una base."], x: 'Quines formes té un monument que coneixeu?|¿Qué formas tiene un monumento que conocéis?', nota: 'Escriu les condicions a la pissarra: les farem servir per comprovar.|Escribe las condiciones en la pizarra: las usaremos para comprobar.' },
      { id: 's3', k: 'anim', t: "De l'encàrrec a la peça|Del encargo a la pieza", anim: 'p14proc', x: 'Si una prova falla, es torna enrere i es millora.|Si una prueba falla, se vuelve atrás y se mejora.', nota: "Remarca que fabricar és l'últim pas, no el primer.|Remarca que fabricar es el último paso, no el primero." },
      { id: 's4', k: 'anim', t: "L'esbós amb cotes|El boceto con cotas", anim: 'p14sketch', x: 'Una peça del dibuix, una línia de codi.|Una pieza del dibujo, una línea de código.', nota: "Dibuixa a la pissarra l'alçat de l'obelisc amb les cotes mentre passa l'animació.|Dibuja en la pizarra el alzado del obelisco con las cotas mientras pasa la animación." },
      { id: 's5', k: 'media', t: "L'obelisc de l'estudi|El obelisco del estudio", media: { k: 'model', prog: OBE }, code: "base: 0 → 8 · sòcol: 8 → 14 · agulla: 14 → 74 · bola: 72 → 84|base: 0 → 8 · zócalo: 8 → 14 · aguja: 14 → 74 · bola: 72 → 84", nota: 'Calculeu junts on comença i on acaba cada peça.|Calculad juntos dónde empieza y dónde acaba cada pieza.' },
      { id: 's6', k: 'anim', t: 'Peces soldades|Piezas soldadas', anim: 'p14fuse', x: 'Si es toquen en un punt, es poden separar. Encasta-les 1 o 2 mm.|Si se tocan en un punto, se pueden separar. Encájalas 1 o 2 mm.', nota: "Per això la bola té el centre a 78 i no a 80.|Por eso la bola tiene el centro en 78 y no en 80." },
      { id: 's7', k: 'anim', t: "Les comprovacions d'un enginyer|Las comprobaciones de un ingeniero", anim: 'p14check', nota: "Són les mateixes que l'app marca en directe al projecte.|Son las mismas que la app marca en directo en el proyecto." },
      { id: 's8', k: 'activitat', t: "L'esbós amb cotes|El boceto con cotas", timer: 8, punts: ["Dibuixa l'alçat: almenys 4 peces.|Dibuja el alzado: al menos 4 piezas.", 'Posa-hi les cotes en mil·límetres.|Ponle las cotas en milímetros.', 'Escriu la z on comença cada peça.|Escribe la z donde empieza cada pieza.', 'Comprova que cap a la caixa.|Comprueba que cabe en la caja.'], nota: 'Individual, amb la fitxa. Cada quadre = 10 mm.|Individual, con la ficha. Cada cuadro = 10 mm.' },
      { id: 's9', k: 'pregunta', t: "S'entén el teu esbós?|¿Se entiende tu boceto?", x: "Ensenya'l a un company/a: sap dir on va cada peça i quant fa d'alt?|Enséñaselo a un compañero/a: ¿sabe decir dónde va cada pieza y cuánto mide de alto?", nota: '2 minuts per parelles abans d\'anar a l\'ordinador.|2 minutos por parejas antes de ir al ordenador.' },
      { id: 's10', k: 'repte', t: "A l'ordinador: l'obelisc pas a pas|En el ordenador: el obelisco paso a paso", punts: ['Prediu i troba els errors de les propostes.|Predice y encuentra los errores de las propuestas.', 'Base, sòcol, agulla i bola, amb el fantasma.|Base, zócalo, aguja y bola, con el fantasma.', "Opcional: l'obelisc de 110 mm.|Opcional: el obelisco de 110 mm."], nota: 'Recorda: la z és on acaba la peça de sota.|Recuerda: la z es donde acaba la pieza de abajo.' },
      { id: 's11', k: 'media', t: "L'agulla, a sobre del sòcol|La aguja, encima del zócalo", media: { k: 'model', prog: OBE3 }, nota: "Per a qui s'encalli al pas 3: l'agulla comença a 8 + 6 = 14.|Para quien se atasque en el paso 3: la aguja empieza en 8 + 6 = 14." },
      { id: 's12', k: 'concepte', t: 'On comença la bola?|¿Dónde empieza la bola?', x: "La punta és a z = 74. Una bola de 12 mm que la toqués tindria el centre a 80; perquè hi entri 2 mm, el centre va a 78.|La punta está en z = 74. Una bola de 12 mm que la tocara tendría el centro en 80; para que entre 2 mm, el centro va en 78.", code: 'mou(0, 0, 78) esfera(12)|mueve(0, 0, 78) esfera(12)', anim: 'p14fuse', nota: "Projecta-ho quan arribin al pas 4.|Proyéctalo cuando lleguen al paso 4." },
      { id: 's13', k: 'repte', t: 'El teu monument per al concurs|Tu monumento para el concurso', punts: ['Almenys 4 formes, a partir del teu esbós.|Al menos 4 formas, a partir de tu boceto.', 'Una sola peça que toca la placa.|Una sola pieza que toca la placa.', 'Cap en 100 × 100 × 120 mm, amb base ampla.|Cabe en 100 × 100 × 120 mm, con base ancha.'], nota: "L'app marca les condicions en directe. Es desa a «Projectes».|La app marca las condiciones en directo. Se guarda en «Proyectos»." },
      { id: 's14', k: 'activitat', t: 'La galeria del concurs|La galería del concurso', timer: 3, punts: ['Presenta el teu monument: mides i base.|Presenta tu monumento: medidas y base.', "Explica una millora que hi has fet.|Explica una mejora que le has hecho.", 'Els altres el valoren amb la rúbrica.|Los demás lo valoran con la rúbrica.'], nota: 'Dos o tres voluntaris. La rúbrica és a la fitxa.|Dos o tres voluntarios. La rúbrica está en la ficha.' },
      { id: 's15', k: 'resum', t: 'Avui hem après…|Hoy hemos aprendido…', punts: ['El procés tecnològic, de l\'encàrrec a la peça.|El proceso tecnológico, del encargo a la pieza.', 'La z de cada peça és la suma de les alçades de sota.|La z de cada pieza es la suma de las alturas de abajo.', "Les peces s'encasten perquè sigui una sola peça estable.|Las piezas se encajan para que sea una sola pieza estable."], nota: 'Llegiu-ho junts.|Leedlo juntos.' },
      { id: 's16', k: 'tiquet', t: 'Tiquet de sortida|Ticket de salida', punts: ['Base de 8 mm i columna de 30: on comença la peça següent?|Base de 8 mm y columna de 30: ¿dónde empieza la pieza siguiente?', "Una condició que ha de complir una maqueta abans d'imprimir-la.|Una condición que tiene que cumplir una maqueta antes de imprimirla."], nota: 'En un paper, abans de sortir.|En un papel, antes de salir.' }
    ],
    print: [{ id: 'p1', t: "Fitxa: l'esbós amb cotes|Ficha: el boceto con cotas", k: 'fitxa', intro: "Dibuixa el teu monument vist de cara. Cada quadre del paper fa 10 mm. Ha de cabre en 100 × 100 × 120 mm.|Dibuja tu monumento visto de frente. Cada cuadro del papel mide 10 mm. Tiene que caber en 100 × 100 × 120 mm.",
      items: [{ q: "Dibuixa l'alçat del monument (almenys 4 peces) i posa-hi les cotes.|Dibuja el alzado del monumento (al menos 4 piezas) y ponle las cotas.", big: true, sol: 'Resposta oberta: alçat amb cotes de cada peça i una base més ampla que la resta.|Respuesta abierta: alzado con cotas de cada pieza y una base más ancha que el resto.' },
        { q: "Fes una llista de les peces de baix a dalt amb la forma, les mides i la z on comença cadascuna.|Haz una lista de las piezas de abajo arriba con la forma, las medidas y la z donde empieza cada una.", big: true, sol: "Exemple (l'obelisc): base cub 50 × 50 × 8 a z = 0; sòcol cilindre 30 × 6 a z = 8; agulla con 20, 60, 8 a z = 14; bola esfera 12 amb el centre a z = 78.|Ejemplo (el obelisco): base cubo 50 × 50 × 8 en z = 0; zócalo cilindro 30 × 6 en z = 8; aguja cono 20, 60, 8 en z = 14; bola esfera 12 con el centro en z = 78." },
        { q: "Quina alçada total té? Cap en 120 mm?|¿Qué altura total tiene? ¿Cabe en 120 mm?", sol: 'La suma de totes les alçades ha de ser 120 mm o menys.|La suma de todas las alturas tiene que ser 120 mm o menos.' }] },
      { id: 'p2', t: 'Fitxa: la rúbrica del concurs|Ficha: la rúbrica del concurso', k: 'fitxa', intro: "Valora el monument d'un company/a. Primer escriu una cosa ben feta i després una millora.|Valora el monumento de un compañero/a. Primero escribe algo bien hecho y después una mejora.",
      items: [{ q: 'Compleix les tres condicions (caixa, una sola peça, estable)? Com ho saps?|¿Cumple las tres condiciones (caja, una sola pieza, estable)? ¿Cómo lo sabes?', sol: "Ho diuen les comprovacions de l'app i la base ampla.|Lo dicen las comprobaciones de la app y la base ancha." },
        { q: "Què és el que està més ben fet?|¿Qué es lo que está mejor hecho?", sol: 'Resposta oberta.|Respuesta abierta.' }, { q: 'Quina millora li proposaries?|¿Qué mejora le propondrías?', sol: 'Resposta oberta.|Respuesta abierta.' }] }]
  },
  /* ---------- Sessió 5 · Taller: el porta-noms de la taula ---------- */
  'p1-5': (() => {
    const NB = { id: 'b1', t: 'rbox', s: [100, 40, 6], p: [0, 0, 3], cr: 2, c: '#3D7BF4' };
    const NFLAT = { parts: [{ id: 'a1', t: 'rbox', s: [90, 30, 4], p: [0, 0, 2], cr: 2, c: '#F7C531' }, { id: 'a2', t: 'text', txt: 'BIT', s: [22.08, 12, 3], p: [0, 0, 5.5], c: '#E8453C' }] };
    const NHOLD = { parts: [NB, { id: 'pl', t: 'rbox', s: [90, 30, 4], p: [0, 4.518, 18.54], r: [75, 0, 0], cr: 2, g: 'nom', c: '#F7C531' }, { id: 'tx', t: 'text', txt: 'BIT', s: [22.08, 12, 3], p: [0, 1.137, 19.446], r: [75, 0, 0], g: 'nom', c: '#E8453C' }] };
    const CODE = 'mou(0, 0, 3) arrodonit(100, 40, 6, 2, centrat)\nmou(0, 4.518, 18.54) gira(75, 0, 0) arrodonit(90, 30, 4, 2, centrat)\nmou(0, 1.137, 19.446) gira(75, 0, 0) text("BIT", 12, 3, centrat)|mueve(0, 0, 3) redondeado(100, 40, 6, 2, centrado)\nmueve(0, 4.518, 18.54) gira(75, 0, 0) redondeado(90, 30, 4, 2, centrado)\nmueve(0, 1.137, 19.446) gira(75, 0, 0) texto("BIT", 12, 3, centrado)';
    return {
    obj: ["L'alumne/a fa un objecte útil amb l'editor directe: formes, cotes, posició, gir i grups.|El alumno/a hace un objeto útil con el editor directo: formas, cotas, posición, giro y grupos.", "L'alumne/a fa servir la forma Text per posar un nom en relleu que càpiga a la placa.|El alumno/a usa la forma Texto para poner un nombre en relieve que quepa en la placa.",
      "L'alumne/a relaciona el model de l'editor amb el seu codi (una línia per peça) i el modifica canviant un número.|El alumno/a relaciona el modelo del editor con su código (una línea por pieza) y lo modifica cambiando un número.", "L'alumne/a solda peces fent que comparteixin volum (2 mm) i prepara el model per imprimir-lo (STL).|El alumno/a suelda piezas haciendo que compartan volumen (2 mm) y prepara el modelo para imprimirlo (STL)."],
    comp: ['Tecnologia i digitalització: disseny assistit per ordinador (CAD 3D) i fabricació digital|Tecnología y digitalización: diseño asistido por ordenador (CAD 3D) y fabricación digital', 'Pensament computacional: un mateix model descrit de dues maneres (editor i codi)|Pensamiento computacional: un mismo modelo descrito de dos maneras (editor y código)', 'Matemàtiques: mesura en mil·límetres, angles (15°, 75°) i proporcionalitat de les lletres|Matemáticas: medida en milímetros, ángulos (15°, 75°) y proporcionalidad de las letras', 'Disseny centrat en les persones: un objecte per a algú concret|Diseño centrado en las personas: un objeto para alguien concreto'],
    vocab: [['Editor directe|Editor directo', "L'editor on poses formes a la placa i les mous amb el dit o amb números.|El editor donde pones formas en la placa y las mueves con el dedo o con números."], ['Cota|Cota', 'La mida que es veu a la vista, al costat de la peça triada; es pot tocar per escriure-la.|La medida que se ve en la vista, al lado de la pieza elegida; se puede tocar para escribirla.'], ['Text en relleu|Texto en relieve', 'Lletres que sobresurten de la superfície, amb un gruix.|Letras que sobresalen de la superficie, con un grosor.'], ['Grup|Grupo', 'Diverses peces que es trien, es mouen i es giren juntes.|Varias piezas que se eligen, se mueven y se giran juntas.'], ['STL|STL', "El fitxer de triangles que llegeixen els programes d'impressió 3D.|El archivo de triángulos que leen los programas de impresión 3D."]],
    mat: { aula: ["Un ordinador per alumne/a amb Numi Tech obert a la sessió «Taller: el porta-noms de la taula»|Un ordenador por alumno/a con Numi Tech abierto en la sesión «Taller: el portanombres de la mesa»", 'Projector i la presentació de la sessió|Proyector y la presentación de la sesión', 'Un regle, un llapis i un full per alumne/a per a l\'esbós|Una regla, un lápiz y una hoja por alumno/a para el boceto'],
      imprimir: ["Fitxa: l'esbós del meu porta-noms|Ficha: el boceto de mi portanombres"], prep: ["Provar el pas 2 (inclinar el grup): cal tocar cinc vegades el + de la X a la pestanya Gir i després escriure la posició.|Probar el paso 2 (inclinar el grupo): hay que tocar cinco veces el + de la X en la pestaña Giro y después escribir la posición.", "Si teniu impressora, imprimir-ne un d'exemple (uns 100 × 40 × 33 mm) per ensenyar-lo a l'inici.|Si tenéis impresora, imprimir uno de ejemplo (unos 100 × 40 × 33 mm) para enseñarlo al principio.", 'Pensar què fan els alumnes amb noms molt llargs: lletres més petites, el sobrenom o la placa més llarga.|Pensar qué hacen los alumnos con nombres muy largos: letras más pequeñas, el apodo o la placa más larga.'] },
    plan: [
      { min: 5, t: 'Portes obertes|Puertas abiertas', fase: 'inici', fa: "Presenta l'encàrrec: un porta-noms per a cada taula de l'estudi. Si en tens un d'imprès, fes-lo passar. Pregunta què necessita per aguantar-se dret i llegir-se bé.|Presenta el encargo: un portanombres para cada mesa del estudio. Si tienes uno impreso, hazlo pasar. Pregunta qué necesita para aguantarse de pie y leerse bien.",
        diu: ["Per què la placa no és del tot vertical?|¿Por qué la placa no es del todo vertical?", 'Què passaria si la base fos estreta?|¿Qué pasaría si la base fuera estrecha?'], slides: ['s1', 's2'], app: 'Encara no: pantalles abaixades.|Todavía no: pantallas bajadas.', org: 'Tot el grup|Todo el grupo' },
      { min: 10, t: "L'editor i el codi|El editor y el código", fase: 'teoria', fa: "Explica que avui es treballa com en un taller de modelatge, amb l'editor directe, i que per sota l'app escriu un programa. Ensenya la forma Text i la idea de fer la placa plana, agrupar-la i girar-la 75°.|Explica que hoy se trabaja como en un taller de modelado, con el editor directo, y que por debajo la app escribe un programa. Enseña la forma Texto y la idea de hacer la placa plana, agruparla y girarla 75°.",
        diu: ['Cinc tocs de 15°: quants graus són?|Cinco toques de 15°: ¿cuántos grados son?', 'Per què la placa entra 2 mm dins de la base?|¿Por qué la placa entra 2 mm dentro de la base?'], slides: ['s3', 's4', 's5', 's6'], app: "Encara no: tota l'atenció a la projecció.|Todavía no: toda la atención en la proyección.", org: 'Tot el grup|Todo el grupo' },
      { min: 7, t: "L'esbós amb mides|El boceto con medidas", fase: 'desconnectat', fa: "Cada alumne/a dibuixa el seu porta-noms vist de costat (base, placa inclinada) i de cara (el nom). Calcula si el nom hi cap: amb lletres de 12 mm, cada lletra fa uns 8-10 mm d'ample.|Cada alumno/a dibuja su portanombres visto de lado (base, placa inclinada) y de frente (el nombre). Calcula si el nombre cabe: con letras de 12 mm, cada letra mide unos 8-10 mm de ancho.",
        diu: ['Quantes lletres té el teu nom? Hi cap en 90 mm?|¿Cuántas letras tiene tu nombre? ¿Cabe en 90 mm?'], slides: ['s7'], app: 'Encara no: llapis, regle i la fitxa.|Todavía no: lápiz, regla y la ficha.', org: 'Individual|Individual' },
      { min: 23, t: "A l'ordinador: editor i codi|En el ordenador: editor y código", fase: 'ordinador', fa: "Fan els tres passos: la placa amb el nom (editor), inclinar el grup sobre la base (editor) i canviar l'amplada de la base al codi. Passa per les taules al pas 2: comproveu que han tocat la placa (es tria el grup) abans de girar. Demana que toquin el botó «Codi» després de cada pas.|Hacen los tres pasos: la placa con el nombre (editor), inclinar el grupo sobre la base (editor) y cambiar la anchura de la base en el código. Pasa por las mesas en el paso 2: comprobad que han tocado la placa (se elige el grupo) antes de girar. Pide que toquen el botón «Código» después de cada paso.",
        diu: ['Quina línia del codi és la base? Com ho saps?|¿Qué línea del código es la base? ¿Cómo lo sabes?', 'Per què el codi té decimals a les posicions?|¿Por qué el código tiene decimales en las posiciones?'], slides: ['s8', 's9', 's10', 's11'], app: "Sessió «Taller: el porta-noms de la taula», fins a «El teu porta-noms».|Sesión «Taller: el portanombres de la mesa», hasta «Tu portanombres».", org: 'Individual|Individual' },
      { min: 10, t: 'El teu porta-noms|Tu portanombres', fase: 'crea', fa: "Cada alumne/a fa el seu: el nom, els colors i un detall propi. Abans de desar, que mirin les comprovacions i el codi, i que descarreguin l'STL. Es desa a «Projectes».|Cada alumno/a hace el suyo: el nombre, los colores y un detalle propio. Antes de guardar, que miren las comprobaciones y el código, y que descarguen el STL. Se guarda en «Proyectos».",
        diu: ["Què li has afegit? Continua sent una sola peça?|¿Qué le has añadido? ¿Sigue siendo una sola pieza?"], slides: ['s12', 's13'], app: 'Pas «El teu porta-noms».|Paso «Tu portanombres».', org: 'Individual|Individual' },
      { min: 5, t: 'Tancament|Cierre', fase: 'tancament', fa: "Algunes persones ensenyen el seu porta-noms i llegeixen una línia del seu codi. Repassa les tres idees i el tiquet de sortida.|Algunas personas enseñan su portanombres y leen una línea de su código. Repasa las tres ideas y el ticket de salida.", diu: ['Què et mostra el botó «Codi»?|¿Qué te muestra el botón «Código»?'], slides: ['s14', 's15'], app: "Les últimes preguntes i «Com t'ha anat?».|Las últimas preguntas y «¿Cómo te ha ido?».", org: 'Tot el grup|Todo el grupo' }
    ],
    errors: [["Posa el text a z = 0 i queda enterrat dins de la placa.|Pone el texto en z = 0 y queda enterrado dentro de la placa.", "A Posició, la z és l'alçada de la base de la peça: el text ha de començar on acaba la placa, a z = 4.|En Posición, la z es la altura de la base de la pieza: el texto tiene que empezar donde acaba la placa, en z = 4."],
      ['Gira només la placa i el nom es queda pla.|Gira solo la placa y el nombre se queda plano.', "Al pas 2 són un grup i es trien juntes. Al projecte no ho són (així es pot canviar el nom tocant-lo): per girar-les juntes, que toqui la placa, «Més peces», el nom i «Agrupa» abans de girar.|En el paso 2 son un grupo y se eligen juntas. En el proyecto no lo son (así se puede cambiar el nombre tocándolo): para girarlas juntas, que toque la placa, «Más piezas», el nombre y «Agrupa» antes de girar."],
      ['Deixa la placa a sobre de la base, només tocant-la, i surt «no és una sola peça».|Deja la placa encima de la base, solo tocándola, y sale «no es una sola pieza».', "Que la faci entrar 2 mm dins: z = 4 amb una base de 6 mm. Així comparteixen volum i queden soldades.|Que la haga entrar 2 mm dentro: z = 4 con una base de 6 mm. Así comparten volumen y quedan soldadas."]],
    diff: { mes: "Afegir-hi un forat per a un llapis o una ranura per a un mòbil, i fer el porta-noms amb dues cares (un nom a cada costat). Al codi, canviar també l'angle de la placa i corregir-ne la posició.|Añadirle un agujero para un lápiz o una ranura para un móvil, y hacer el portanombres con dos caras (un nombre a cada lado). En el código, cambiar también el ángulo de la placa y corregir su posición.",
      menys: "Fer només el pas 1 i el pas 2 seguint la diapositiva amb els números, i al projecte canviar només el text. El professor/a ensenya el botó «Codi» a la pantalla gran.|Hacer solo el paso 1 y el paso 2 siguiendo la diapositiva con los números, y en el proyecto cambiar solo el texto. El profesor/a enseña el botón «Código» en la pantalla grande." },
    aval: { ticket: ["Què vol dir la z de Posició a l'editor?|¿Qué quiere decir la z de Posición en el editor?", 'Escriu la línia del codi que fa la base i digues quin número és l\'amplada.|Escribe la línea del código que hace la base y di qué número es la anchura.'],
      rubric: [["Ús de l'editor|Uso del editor", 'Col·loca, gira i agrupa peces escrivint les cotes i la posició exactes.|Coloca, gira y agrupa piezas escribiendo las cotas y la posición exactas.', 'Ho fa a ull, arrossegant, i les mides no són exactes.|Lo hace a ojo, arrastrando, y las medidas no son exactas.'],
        ['Editor i codi|Editor y código', "Troba al codi la línia de cada peça i en canvia el número que toca.|Encuentra en el código la línea de cada pieza y cambia el número que toca.", 'Veu el codi però no sap quina línia és cada peça.|Ve el código pero no sabe qué línea es cada pieza.'],
        ['Fabricació|Fabricación', 'Una sola peça, estable, amb el nom llegible i l\'STL descarregat.|Una sola pieza, estable, con el nombre legible y el STL descargado.', 'Té peces soltes o el nom no hi cap.|Tiene piezas sueltas o el nombre no cabe.']] },
    casa: "Mesura una taula de casa i pensa on posaries el teu porta-noms. Quin nom o quina paraula hi escriuries per a cada persona de la família?|Mide una mesa de casa y piensa dónde pondrías tu portanombres. ¿Qué nombre o qué palabra escribirías para cada persona de la familia?",
    intro: "Primera sessió de taller del Nivell 2: un objecte útil fet amb l'editor directe, com en un taller de modelatge, que serveix de pont cap al codi. L'alumnat veu que l'editor escriu un programa (botó «Codi») i el modifica canviant un sol número.|Primera sesión de taller del Nivel 2: un objeto útil hecho con el editor directo, como en un taller de modelado, que sirve de puente hacia el código. El alumnado ve que el editor escribe un programa (botón «Código») y lo modifica cambiando un solo número.",
    claus: ["L'editor directe i el codi són el mateix model: el botó «Codi» el mostra.|El editor directo y el código son el mismo modelo: el botón «Código» lo muestra.", 'La forma Text fa un nom en relleu; la z de Posició és on comença.|La forma Texto hace un nombre en relieve; la z de Posición es donde empieza.', 'Pla primer, agrupar i girar el grup: 5 × 15° = 75°.|Plano primero, agrupar y girar el grupo: 5 × 15° = 75°.', 'Peces soldades: una entra 2 mm dins de l\'altra.|Piezas soldadas: una entra 2 mm dentro de la otra.'],
    prev: ['Haver fet les sessions 1-4 de la unitat 1 (cub, mou, centrat).|Haber hecho las sesiones 1-4 de la unidad 1 (cubo, mueve, centrado).', 'Saber fer servir el ratolí i escriure números en un camp.|Saber usar el ratón y escribir números en un campo.', 'No cal saber girar amb codi: gira es treballa a la unitat 2.|No hace falta saber girar con código: gira se trabaja en la unidad 2.'],
    faq: [["Per què fem servir l'editor si el curs és de codi?|¿Por qué usamos el editor si el curso es de código?", "Perquè molts dissenys es comencen a mà i es retoquen amb codi, i al revés. Veure el mateix model de les dues maneres ajuda a entendre què fa cada instrucció.|Porque muchos diseños se empiezan a mano y se retocan con código, y al revés. Ver el mismo modelo de las dos maneras ayuda a entender qué hace cada instrucción."],
      ['Per què el codi de l\'editor té decimals i «centrat»?|¿Por qué el código del editor tiene decimales y «centrado»?', "L'editor guarda el centre de cada peça i l'escriu tal com és, amb «centrat». Després d'un gir, les posicions no solen ser números rodons.|El editor guarda el centro de cada pieza y lo escribe tal como es, con «centrado». Después de un giro, las posiciones no suelen ser números redondos."],
      ['Es pot fer servir qualsevol lletra?|¿Se puede usar cualquier letra?', "Majúscules, la Ç, la Ñ, les vocals accentuades, els números i alguns símbols. La resta surt com «?».|Mayúsculas, la Ç, la Ñ, las vocales acentuadas, los números y algunos símbolos. El resto sale como «?»."]],
    tec: [['El nom no es veu: queda dins de la placa.|El nombre no se ve: queda dentro de la placa.', "Pestanya Posició: z = 4 (el gruix de la placa). També va bé Alinea → «A sobre de la peça de sota».|Pestaña Posición: z = 4 (el grosor de la placa). También va bien Alinea → «Encima de la pieza de debajo»."],
      ['En girar, només gira una peça.|Al girar, solo gira una pieza.', "Comproveu que estan agrupades: tocar-ne una ha de triar totes dues. Si no, «Més peces» i «Agrupa».|Comprobad que están agrupadas: tocar una tiene que elegir las dos. Si no, «Más piezas» y «Agrupa»."],
      ['No troben el botó «Codi».|No encuentran el botón «Código».', "És a la barra de sota de la vista 3D, amb el símbol &lt;/&gt;. Obre una finestra amb el codi i el botó per descarregar el .scad.|Está en la barra de debajo de la vista 3D, con el símbolo &lt;/&gt;. Abre una ventana con el código y el botón para descargar el .scad."]],
    extra: ['Fer el porta-noms de tota la família, cadascun amb un color.|Hacer el portanombres de toda la familia, cada uno con un color.', "Afegir-hi un forat per a un llapis (un forat rodó a la base).|Añadirle un agujero para un lápiz (un agujero redondo en la base).", 'Descarregar el .scad i obrir-lo amb OpenSCAD.|Descargar el .scad y abrirlo con OpenSCAD.'],
    trans: ['Unitat següent: moure i girar amb codi (mou i gira, i per què el gir és al voltant de l\'origen).|Unidad siguiente: mover y girar con código (mueve y gira, y por qué el giro es alrededor del origen).', 'Tecnologia: el procés de disseny d\'un objecte per a una persona concreta.|Tecnología: el proceso de diseño de un objeto para una persona concreta.'],
    slides: [
      { id: 's1', k: 'portada', t: 'Taller: el porta-noms|Taller: el portanombres', x: "De l'editor al codi en una sessió|Del editor al código en una sesión", nota: "Si tens un porta-noms imprès, ensenya'l ara.|Si tienes un portanombres impreso, enséñalo ahora." },
      { id: 's2', k: 'pregunta', t: "Què necessita per aguantar-se?|¿Qué necesita para aguantarse?", x: 'Una base, una placa inclinada i un nom que es llegeixi bé. Quines mides li posaries?|Una base, una placa inclinada y un nombre que se lea bien. ¿Qué medidas le pondrías?', nota: "Recull idees: base ampla, placa una mica enrere, lletres grans.|Recoge ideas: base ancha, placa un poco hacia atrás, letras grandes." },
      { id: 's3', k: 'anim', t: 'Editor i codi|Editor y código', anim: 'p15edcode', x: 'Cada peça és una línia de codi.|Cada pieza es una línea de código.', nota: "Assenyala cada peça i la seva línia. El botó «Codi» és a sota de la vista.|Señala cada pieza y su línea. El botón «Código» está debajo de la vista." },
      { id: 's4', k: 'media', t: 'El text en relleu|El texto en relieve', media: { k: 'model', model: NFLAT }, nota: 'Lletres de 12 mm i 3 de gruix, a z = 4: just a sobre de la placa.|Letras de 12 mm y 3 de grosor, en z = 4: justo encima de la placa.' },
      { id: 's5', k: 'anim', t: 'Pla primer, inclinat després|Plano primero, inclinado después', anim: 'p15tilt', x: 'Agrupa, gira 5 × 15° i posa-la a la base.|Agrupa, gira 5 × 15° y ponla en la base.', nota: 'Fes notar que el gir és en x: la placa s\'aixeca cap enrere.|Haz notar que el giro es en x: la placa se levanta hacia atrás.' },
      { id: 's6', k: 'concepte', t: 'Soldades, no tocant-se|Soldadas, no tocándose', x: 'La base fa 6 mm i la placa comença a z = 4: entra 2 mm a dins i en surt una sola peça.|La base mide 6 mm y la placa empieza en z = 4: entra 2 mm dentro y sale una sola pieza.', anim: 'p14fuse', nota: 'És la mateixa idea de la bola de l\'obelisc.|Es la misma idea de la bola del obelisco.' },
      { id: 's7', k: 'activitat', t: "L'esbós del porta-noms|El boceto del portanombres", timer: 6, punts: ['Dibuixa\'l de costat i de cara.|Dibújalo de lado y de frente.', 'Compta les lletres del nom.|Cuenta las letras del nombre.', 'Hi cap en 90 mm?|¿Cabe en 90 mm?'], nota: 'Amb lletres de 12 mm, cada lletra fa uns 8-10 mm d\'ample.|Con letras de 12 mm, cada letra mide unos 8-10 mm de ancho.' },
      { id: 's8', k: 'repte', t: "A l'ordinador|En el ordenador", punts: ['Pas 1: la placa i el nom.|Paso 1: la placa y el nombre.', 'Pas 2: inclina el grup sobre la base.|Paso 2: inclina el grupo sobre la base.', 'Pas 3: canvia la base al codi.|Paso 3: cambia la base en el código.'], nota: 'Després de cada pas, el botó «Codi».|Después de cada paso, el botón «Código».' },
      { id: 's9', k: 'media', t: "El porta-noms d'en Bit|El portanombres de Bit", media: { k: 'model', model: NHOLD }, nota: 'Per a qui s\'encalli al pas 2: Gir X + cinc vegades; Posició y = 4, z = 4.|Para quien se atasque en el paso 2: Giro X + cinco veces; Posición y = 4, z = 4.' },
      { id: 's10', k: 'concepte', t: 'El codi del porta-noms|El código del portanombres', x: 'Tres peces, tres línies: la base, la placa i el nom.|Tres piezas, tres líneas: la base, la placa y el nombre.', code: CODE, nota: 'Llegiu-lo junts: mou, gira i la forma amb les mides.|Leedlo juntos: mueve, gira y la forma con las medidas.' },
      { id: 's11', k: 'concepte', t: 'Un número, un canvi|Un número, un cambio', x: "arrodonit(100, 40, 6, 2, centrat): el primer número és l'amplada. 100 → 120 i la base creix.|redondeado(100, 40, 6, 2, centrado): el primer número es la anchura. 100 → 120 y la base crece.", nota: "Com que la base és centrada, creix 10 mm per cada costat.|Como la base está centrada, crece 10 mm por cada lado." },
      { id: 's12', k: 'repte', t: 'El teu porta-noms|Tu portanombres', punts: ['El teu nom en relleu.|Tu nombre en relieve.', 'Una sola peça, estable.|Una sola pieza, estable.', 'Un detall teu i l\'STL.|Un detalle tuyo y el STL.'], nota: 'Es desa a «Projectes».|Se guarda en «Proyectos».' },
      { id: 's13', k: 'concepte', t: "Abans de descarregar l'STL|Antes de descargar el STL", x: "Comprova que és una sola peça, que toca la placa i que el nom es llegeix de cara. La placa inclinada 15° s'imprimeix sense suports.|Comprueba que es una sola pieza, que toca la placa y que el nombre se lee de frente. La placa inclinada 15° se imprime sin soportes.", anim: 'p14check', nota: 'Si teniu impressora, en podeu imprimir alguns per a les portes obertes.|Si tenéis impresora, podéis imprimir algunos para las puertas abiertas.' },
      { id: 's14', k: 'resum', t: 'Avui hem après…|Hoy hemos aprendido…', punts: ["L'editor i el codi són el mateix model.|El editor y el código son el mismo modelo.", 'Pla primer, agrupar i girar.|Plano primero, agrupar y girar.', 'Peces soldades: 2 mm a dins.|Piezas soldadas: 2 mm dentro.'], nota: 'Llegiu-ho junts.|Leedlo juntos.' },
      { id: 's15', k: 'tiquet', t: 'Tiquet de sortida|Ticket de salida', punts: ['Què vol dir la z de Posició?|¿Qué quiere decir la z de Posición?', 'Quin número de la línia de la base és l\'amplada?|¿Qué número de la línea de la base es la anchura?'], nota: 'En un paper, abans de sortir.|En un papel, antes de salir.' }
    ],
    print: [{ id: 'p1', t: "Fitxa: l'esbós del meu porta-noms|Ficha: el boceto de mi portanombres", k: 'fitxa', intro: 'Dibuixa i calcula abans de modelar.|Dibuja y calcula antes de modelar.',
      items: [{ q: 'El nom que hi aniran: … (… lletres). Amb lletres de 12 mm, quant farà d\'ample, més o menys?|El nombre que irá: … (… letras). Con letras de 12 mm, ¿cuánto medirá de ancho, más o menos?', sol: 'Unes 8-10 mm per lletra: un nom de 6 lletres fa uns 50-60 mm.|Unos 8-10 mm por letra: un nombre de 6 letras mide unos 50-60 mm.' },
        { q: 'Dibuixa el porta-noms de costat: base de 6 mm i placa inclinada 15° enrere.|Dibuja el portanombres de lado: base de 6 mm y placa inclinada 15° hacia atrás.', sol: 'La placa recolza a la base i hi entra 2 mm.|La placa se apoya en la base y entra 2 mm.' },
        { q: 'A quina z ha de començar el text a sobre d\'una placa de 4 mm?|¿En qué z tiene que empezar el texto encima de una placa de 4 mm?', sol: 'A z = 4.|En z = 4.' }] }]
    };
  })()
  };
})());

